const Q=[{"id":1,"topic":"踏切","fig":"railsig","q":"信号機のある踏切で青信号が表示されているときは、一時停止せずに通過できる。","a":true,"ex":"青信号の踏切は、安全を確かめれば一時停止しなくてよい。信号のない踏切は必ず一時停止。","chapter":6,"section":1,"concept":"merged-1"},{"id":2,"topic":"携帯電話","fig":"phone","q":"携帯電話を手に持って通話することは、車が完全に停止しているときでも禁止されている。","a":false,"ex":"この禁止規定は停止中を除きます。ただし、少しでも動いていれば走行中です。再発進する前に使用をやめ、周囲を確認しましょう。","chapter":5,"section":1,"concept":"merged-2"},{"id":3,"topic":"駐停車","fig":"dist","q":"消火栓から5m以内は駐車禁止だが、ほかに駐停車を禁止する条件がなく、運転者がすぐ運転できる状態で5分以内の荷物の積みおろしをする停車はできる。","a":true,"ex":"消火栓から5m以内は「駐車禁止」です。ただし、5分以内でも運転者が離れてすぐ運転できない状態は駐車になります。","chapter":null,"section":8,"concept":"original-3"},{"id":4,"topic":"駐停車","fig":"dist","q":"踏切とその端から前後10m以内の場所では、人の乗り降りのための停車であっても、することはできない。","a":true,"ex":"踏切は前後10m以内が駐停車禁止。","chapter":null,"section":8,"concept":"merged-4"},{"id":5,"topic":"駐停車","fig":"dist","q":"火災報知機から3m以内の場所は駐車が禁止されているが、停車することはできる。","a":false,"ex":"火災報知機は1m以内。3mは車庫・駐車場の出入口。","chapter":null,"section":8,"concept":"original-5"},{"id":6,"topic":"駐停車","fig":"dist","q":"車庫の自動車用出入口から3m以内でも、人の乗り降りのための停車はできる。","a":true,"ex":"車庫の出入口から3m以内という条件は駐車禁止です。すぐ運転できる状態で人が乗り降りする停車は可能ですが、別の駐停車禁止の規制が重なる場合はできません。","chapter":null,"section":8,"concept":"original-6"},{"id":7,"topic":"駐停車","fig":"dist","q":"踏切とその端から前後5m以内の場所は駐停車禁止だが、5mを超えていれば駐停車してもよい。","a":false,"ex":"踏切は前後10m。数字のすり替え。","chapter":null,"section":8,"concept":"merged-4"},{"id":8,"topic":"駐停車","fig":"dist","q":"消火栓から5m以内の場所は駐停車禁止なので、人の乗り降りのための停車もすることができない。","a":false,"ex":"消火栓から5m以内は駐車禁止です。他の駐停車禁止の条件に当たらなければ、すぐ運転できる状態で人が乗り降りするための停車はできます。","chapter":null,"section":8,"concept":"original-8"},{"id":9,"topic":"駐停車","fig":"dist","q":"バスの停留所の標示板から10m以内の場所は、時間に関係なく常に駐停車禁止である。","a":false,"ex":"バス停は運行時間中に限り駐停車禁止。","chapter":null,"section":8,"concept":"original-9"},{"id":10,"topic":"追い越し","fig":"hill","q":"こう配の急な上り坂では、前方の見通しが悪くなるため、追い越しが禁止されている。","a":false,"ex":"追い越し禁止は急な下り坂。上り坂は頂上付近だけ。","chapter":5,"section":6,"concept":"original-10"},{"id":11,"topic":"追い越し","fig":"priority","q":"優先道路を通行している場合でも、交差点とその手前30m以内では追い越しが禁止されている。","a":false,"ex":"優先道路を通行中は「交差点とその手前30m」の追い越し禁止から除かれます。ただし、横断歩道などの禁止や、安全確認の義務は別です。","chapter":5,"section":6,"concept":"merged-11"},{"id":12,"topic":"交差点","fig":"oneway","q":"一方通行の道路で右折するときは、あらかじめ道路の中央に寄ってから右折する。","a":false,"ex":"一方通行では右端に寄って右折する。","chapter":5,"section":7,"concept":"original-12"},{"id":13,"topic":"標識","fig":"signs","q":"図の標識は、この標識がある側から車両が進入することを禁止するものである。","a":true,"ex":"この標識自体は、標識のある側からの進入を禁止するものです。反対側に別の規制があるときは、その規制にも従います。","chapter":1,"section":2,"concept":"merged-13"},{"id":14,"topic":"標識","fig":"signs","q":"図の2つの標識は、どちらも車を一時停止させることを意味する。","a":false,"ex":"左の「止まれ」は一時停止、右の「徐行」は直ちに停止できる速度で進むことです。形はどちらも逆三角形ですが、色と意味は異なります。","revised":true,"chapter":1,"section":2,"concept":"original-14"},{"id":15,"topic":"標識","fig":"horn","q":"図の標識がある場所では、警音器を鳴らさなければならない。","a":true,"ex":"鳴らす義務がある場所。見通しの悪い山道などにある。","chapter":1,"section":2,"concept":"original-15"},{"id":16,"topic":"歩行者保護","fig":"safety","q":"安全地帯のそばを通るときは、歩行者がいるかどうかに関係なく、徐行しなければならない。","a":false,"ex":"徐行が必要なのは歩行者がいるときだけ。","chapter":5,"section":3,"concept":"original-16"},{"id":17,"topic":"緊急自動車","fig":"emergency","q":"交差点付近以外の場所で緊急自動車が近づいてきたときは、必ず一時停止しなければならない。","a":false,"ex":"交差点付近以外では左に寄って進路を譲ればよい。","chapter":5,"section":2,"concept":"merged-17"},{"id":18,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道を渡ろうとする人がいないことが明らかな場合でも、その手前で停止できるような速度で進まなければならない。","a":false,"ex":"いないことが明らかなら、そのまま進める。","chapter":5,"section":3,"concept":"merged-18"},{"id":19,"topic":"通行の基本","fig":"keepleft","q":"歩道や路側帯のない道路では、車は道路の左側を、歩行者は道路の右側端を通行する。","a":true,"ex":"車は左、人は右。","chapter":5,"section":2,"concept":"original-19"},{"id":20,"topic":"交差点","fig":"priority","q":"優先道路を通行している場合でも、見通しの悪い交差点では徐行しなければならない。","a":false,"ex":"優先道路では「見通しの悪い交差点」という理由だけの徐行義務はありません。ただし右左折、歩行者保護など、別の徐行・停止義務や安全確認は必要です。","chapter":5,"section":7,"concept":"original-20"},{"id":21,"topic":"緊急自動車","fig":"emergency","q":"交差点やその付近で緊急自動車が近づいてきたときは、交差点を避け、道路の左側に寄って一時停止する。","a":true,"ex":"交差点付近は「交差点を避けて左に寄り一時停止」。","chapter":5,"section":2,"concept":"original-21"},{"id":22,"topic":"追い越し","fig":"pass","q":"横断歩道の手前30m以内では、追い越しは禁止されているが、追い抜きは禁止されていない。","a":false,"ex":"横断歩道の手前は追い越しも追い抜きも禁止。","chapter":5,"section":6,"concept":"merged-22"},{"id":23,"topic":"駐停車","fig":"stoppark","q":"5分以内の荷物の積みおろしのための停止は、運転者が車のそばにいてすぐ運転できる状態でも、必ず駐車にあたる。","a":false,"ex":"5分以内で、運転者がすぐ運転できる状態なら停車です。5分を超える場合や、離れてすぐ運転できない場合は駐車です。","chapter":null,"section":8,"concept":"original-23"},{"id":24,"topic":"追い越し","fig":"leftpass","q":"車両通行帯のないトンネルでは、見通しがよい場合でも追い越しが禁止されている。","a":true,"ex":"車両通行帯のないトンネルでは、自動車・一般原付の追い越しは禁止です。通行帯がある場合は、この場所の規定による禁止から除かれます。","chapter":5,"section":6,"concept":"merged-24"},{"id":25,"topic":"歩行者保護","fig":"protect","q":"子どもが一人で歩いているときは、一時停止か徐行をして、安全に通行できるようにしなければならない。","a":true,"ex":"独り歩きの子どもには、一時停止か徐行をして安全に通れるようにします。白・黄のつえや盲導犬を利用する人、歩行に支障のある高齢者などにも同様の保護が必要です。","chapter":5,"section":3,"concept":"original-25"},{"id":26,"topic":"標識","fig":"signs","q":"図の標識は、駐車も停車も禁止されていることを表している。","a":false,"ex":"1本は駐車禁止。×が駐停車禁止。","chapter":1,"section":2,"concept":"merged-26"},{"id":27,"topic":"標識","fig":"signs","q":"図のような黄色のひし形の標識は、特定の交通方法を禁止したり指定したりする規制標識である。","a":false,"ex":"黄色のひし形は警戒標識。","chapter":1,"section":2,"concept":"merged-27"},{"id":28,"topic":"標識","fig":"signs","q":"図の標識は、時速50kmを超えて運転してはならないことを表している。","a":false,"ex":"図は「最低速度」の標識です。数字の下の青い横線が目印で、時速50kmが最低速度として指定されています。最高速度の標識にはこの横線がありません。","chapter":1,"section":2,"concept":"original-28"},{"id":29,"topic":"運転者の心得","fig":"distance","q":"車間距離は、前の車が急に止まっても追突しないような安全な距離を保つ。","a":true,"ex":"前の車が急に止まっても追突しない距離をとる。","chapter":5,"section":4,"concept":"merged-29"},{"id":30,"topic":"路側帯","fig":"roadside","q":"白の実線1本の路側帯で、幅が0.75mを超えているときは、中に入って駐停車できる。","a":true,"ex":"駐停車できる場所なら、白の実線1本の路側帯に入り、車の左側に0.75m以上の余地を空けます。歩行者の通行を妨げてはいけません。","chapter":null,"section":8,"concept":"merged-30"},{"id":31,"topic":"追い越し","fig":"hidden","q":"横断歩道とその手前30m以内の場所では、追い越しだけでなく、前を走る自動車や原付の側方を通って前に出る追い抜きも禁止されている。","a":true,"ex":"横断歩道とその手前30m以内は、自動車・原付を追い越すことも、横を通って前に出る（追い抜く）ことも禁止。横断する人を見落とさないため。","chapter":5,"section":6,"concept":"merged-22"},{"id":32,"topic":"駐停車","fig":"stoppark","q":"人の乗り降りのための停止は、5分以内なら停車、5分を超えれば駐車になる。","a":false,"ex":"乗り降りそのものには5分の区切りはありません。ただし、客が来るのを待つ「客待ち」や、運転者が離れてすぐ運転できない状態は駐車です。","chapter":null,"section":8,"concept":"original-32"},{"id":33,"topic":"駐停車","fig":"safety","q":"安全地帯の左側とその前後10m以内の場所は、人の乗り降りのためであっても停車することはできない。","a":true,"ex":"安全地帯の横は停車も禁止。","chapter":null,"section":8,"concept":"original-33"},{"id":34,"topic":"緊急自動車","fig":"emergency","q":"交差点の中で緊急自動車が近づいてきたときは、その場で停止して進路を譲る。","a":false,"ex":"交差点を出てから左に寄って一時停止する。","chapter":5,"section":2,"concept":"original-34"},{"id":35,"topic":"合図","fig":"timing","q":"右左折の合図は、右左折しようとする地点の約3秒前に行い、右左折が終わるまで続ける。","a":false,"ex":"右左折は30m手前。3秒前は進路変更。","chapter":5,"section":5,"concept":"merged-35"},{"id":36,"topic":"追い越し","fig":"pass","q":"自転車横断帯の手前30m以内では、追い越しだけでなく追い抜きも禁止されている。","a":true,"ex":"横断歩道と同じルール。","chapter":5,"section":6,"concept":"merged-22"},{"id":37,"topic":"駐停車","fig":"hill","q":"坂の頂上付近では駐車は禁止されているが、5分以内の荷物の積みおろしのための停車はできる。","a":false,"ex":"坂の頂上付近と急な坂は駐停車禁止。","chapter":null,"section":8,"concept":"original-37"},{"id":38,"topic":"標識","fig":"signs","q":"図の標識は、標識がある側から車両が入ることを禁止している。","a":true,"ex":"白い横棒は「ここから入るな」。","chapter":1,"section":2,"concept":"merged-13"},{"id":39,"topic":"信号","fig":"signals","q":"黄色の灯火の矢印信号は路面電車に対するもので、自動車や原付は矢印の方向に進むことはできない。","a":true,"ex":"黄色の矢印は路面電車専用。","chapter":1,"section":2,"concept":"original-39"},{"id":40,"topic":"信号","fig":"signals","q":"赤色の灯火の点滅信号では、他の交通に注意して徐行すれば進むことができる。","a":false,"ex":"赤の点滅は一時停止してから進む。","chapter":1,"section":2,"concept":"merged-40"},{"id":41,"topic":"通行の基本","fig":"oneway","q":"車は道路の中央から左の部分を通行するが、一方通行の道路では右側部分も通行できる。","a":true,"ex":"一方通行は対向車がいないので右側も使える。","chapter":5,"section":2,"concept":"merged-41"},{"id":42,"topic":"合図","fig":"timing","q":"右折の合図は、右折しようとする地点から30m手前の地点に達したときに行う。","a":true,"ex":"右左折・転回は30m手前で正しい。","chapter":5,"section":5,"concept":"merged-42"},{"id":43,"topic":"交差点","fig":"rightturn","q":"交差点内で右折待ちをしているときに信号が赤に変わったら、右折してはならない。","a":false,"ex":"すでに交差点内で右折を待っていた自動車は、安全を確認して速やかに出ます。青信号に従って進む車や歩行者等の通行を妨げてはいけません。","chapter":1,"section":2,"concept":"merged-43"},{"id":44,"topic":"交差点","fig":"rightturn","q":"交差点で右折するとき、反対方向から直進してくる二輪車があるときは、その進行を妨げてはならない。","a":true,"ex":"二輪車も直進車なので優先。","chapter":5,"section":7,"concept":"original-44"},{"id":45,"topic":"追い越し","fig":"leftpass","q":"前の車が右折するため道路の中央に寄っているときは、その左側を通行して追い越す。","a":true,"ex":"右折のため中央に寄っている車は、その左側から追い越す（路面電車も原則として左側から）。","chapter":5,"section":6,"concept":"merged-45"},{"id":46,"topic":"追い越し","fig":"leftpass","q":"車両通行帯のないトンネルでは、追い越しだけでなく追い抜きも禁止されている。","a":false,"ex":"この場所の規定で禁止されるのは追い越しです。ただし、進路を変えずに前へ出る場合も、他の規制や安全確認に従う必要があります。","chapter":5,"section":6,"concept":"original-46"},{"id":47,"topic":"路側帯","fig":"roadside2","q":"白の実線1本の路側帯で、幅が0.75m以下のときは、中に入って駐停車できる。","a":false,"ex":"0.75m以下なら入らず車道の左端に。","chapter":null,"section":8,"concept":"merged-30"},{"id":48,"topic":"追い越し","fig":"hill","q":"上り坂の頂上付近では、対向車が見えにくいため、追い越しが禁止されている。","a":true,"ex":"頂上付近は向こうが見えないので禁止。","chapter":5,"section":6,"concept":"merged-48"},{"id":49,"topic":"標識","fig":"signs","q":"図の標識は、数字で示された最高速度を指定する規制標識である。","a":true,"ex":"図は「最高速度40km/h」の規制標識です。白地・赤い枠・青い数字で、数字の下に横線はありません。","chapter":1,"section":2,"concept":"original-49"},{"id":50,"topic":"標識","fig":"signs","q":"図の標識がある道路では、車だけでなく歩行者も通行することができない。","a":true,"ex":"「車両」が付かないので人も車も全部ダメ。","chapter":1,"section":2,"concept":"merged-50"},{"id":51,"topic":"駐停車","fig":"stoppark","q":"停車とは、5分を超える荷物の積みおろしのための停止や、人の乗り降りのための停止をいう。","a":false,"ex":"荷物の積みおろしが5分を超える場合は駐車です。人の乗り降りそのものには5分の区切りはありません。運転者が離れてすぐ運転できない状態も駐車です。","chapter":null,"section":8,"concept":"original-51"},{"id":52,"topic":"信号","fig":"pedsig","q":"歩行者用信号が青の点滅のとき、歩行者は通行車両がなければ横断を開始することができる。","a":false,"ex":"青の点滅は横断を始めてはいけない。車がいなくても同じ。","chapter":1,"section":2,"concept":"original-52"},{"id":53,"topic":"路面電車","fig":"tram","q":"安全地帯のある停留所で、止まっている路面電車に乗り降りする人がいる場合は、徐行して進むことができる。","a":true,"ex":"人は安全地帯にいるので徐行で通れる。安全地帯がなければ後方で停止。","chapter":5,"section":3,"concept":"original-53"},{"id":54,"topic":"合図","fig":"timing2","q":"徐行や停止をするときは、その行為をしようとするときに合図をすればよい。","a":true,"ex":"徐行・停止・後退は「しようとするとき」。","chapter":5,"section":5,"concept":"merged-54"},{"id":55,"topic":"合図","fig":"timing2","q":"後退の合図は、後退しようとする約3秒前に行う。","a":false,"ex":"後退は後退しようとするとき。Rに入れると後退灯がつき合図になる。","chapter":5,"section":5,"concept":"merged-55"},{"id":56,"topic":"合図","fig":"timing2","q":"車が停止するときの合図の時期は、停止しようとするときである。","a":true,"ex":"停止は「しようとするとき」に合図。","chapter":5,"section":5,"concept":"merged-54"},{"id":57,"topic":"速度","fig":"speed","q":"三輪や総排気量660cc以下の普通貨物自動車の一般道路での法定最高速度は、時速50kmである。","a":false,"ex":"三輪や軽貨物を一律50km/hとする区別はありません。2026年9月1日以降、中央線・車両通行帯などがある一般道路は原則60km/h、それらがない一般道路は原則30km/hです。標識等の指定が優先し、自動車専用道路などは別区分です。","revised":true,"chapter":5,"section":4,"concept":"original-57"},{"id":58,"topic":"発進","fig":"wakaba","q":"交通量の多いところで車に乗り降りするときは、できるだけ左側のドアから乗り降りしたほうがよい。","a":true,"ex":"右のドアは後ろから来る車や二輪車とぶつかる危険がある。","chapter":5,"section":1,"concept":"original-58"},{"id":59,"topic":"合図","fig":"timing2","q":"交通量が少ない裏通りを二輪車で右左折する場合は、他の交通に影響がなければ合図をしなくてもよい。","a":false,"ex":"二輪車でも、交通量が少なくても合図は必ず出す。","chapter":5,"section":5,"concept":"original-59"},{"id":60,"topic":"AT車","fig":"atgear","q":"AT車のDはエンジンブレーキの効果が小さいので、急な下り坂では2やL（1）にしてエンジンブレーキを活用したほうがよい。","a":true,"ex":"フットブレーキの使いすぎを防ぐため、ギアを落としてエンジンブレーキを使う。","chapter":5,"section":9,"concept":"original-60"},{"id":61,"topic":"停止距離","fig":"stop60","q":"時速60kmで走行している普通乗用車の停止距離は、乾燥したアスファルト道路で約20m程度である。","a":false,"ex":"教本で使う条件での目安は、空走約17m＋制動約27m＝約44mです。実際には路面・タイヤ・車両・反応時間などによって変わり、44mを保証するものではありません。","chapter":5,"section":4,"concept":"merged-61"},{"id":62,"topic":"交差点","fig":"jam","q":"交通整理が行われていない交差点内で車が渋滞している場合は、対向車に注意し右側を通行して交差点を通過してもよい。","a":false,"ex":"右側（対向車線）にはみ出して抜けてはいけない。","chapter":5,"section":7,"concept":"merged-62"},{"id":63,"topic":"標識・標示","fig":"wakaba","q":"初心運転者（普通免許を受けて1年を経過しない者）は、図のマークを車の前か後ろのどちらかの定められた位置に付けなければならない。","a":false,"ex":"前と後ろの両方に付ける。","chapter":4,"section":1,"concept":"merged-63"},{"id":86,"topic":"路面電車","fig":"tracks","q":"路面電車が通っていなければ、軌道敷内を自動車で通行してもよい。","a":false,"ex":"軌道敷内の走行は原則禁止です。道路外への出入りや右左折のため横切る場合、標識で許可された車などには例外があります。","chapter":5,"section":2,"concept":"merged-86"},{"id":87,"topic":"通行の基本","fig":"buslane","q":"路線バス等優先通行帯は、どんな車でも通行できるが、路線バスが近づいてきたら自動車はすみやかにそこから出なければならない（小型特殊自動車や原付、軽車両は除く）。","a":true,"ex":"優先通行帯は入ってよいが、バスが来たら速やかに出る。混んでいてバスが来ても出られなくなりそうなら、はじめから入らない。","chapter":5,"section":2,"concept":"merged-87"},{"id":88,"topic":"追い越し","fig":"fb30","q":"横断歩道や自転車横断帯の前後30メートル以内は、追い越しが禁止されている。","a":false,"ex":"追い越し禁止は「手前」30m。「前後」が付くのは駐停車禁止の前後5m。","chapter":5,"section":6,"concept":"original-88"},{"id":89,"topic":"標識","fig":"buslane","q":"図の標識がある通行帯で路線バスが近づいてきたとき、普通自動車は速やかに他の通行帯に移らなければならない。","a":true,"ex":"路線バス等優先通行帯です。路線バス等が近づいたら速やかに他の通行帯へ移ります。混雑で出られないおそれがあれば、原則として最初から入りません。","chapter":1,"section":2,"concept":"merged-87"},{"id":90,"topic":"標識・標示","fig":"zones","q":"図の黄色い枠と白い斜線で示された部分は、その中で停止しなければ通過してもよい。","a":false,"ex":"立入り禁止部分は中に入ること自体が禁止。止まらなければ通れるのは白い×の停止禁止部分。","chapter":1,"section":2,"concept":"original-90"},{"id":91,"topic":"運転者の心得","fig":"policeorder","q":"警察官が道路における危険防止の措置として後退や転回をするように指示した場合は、これに従わなくてはならない。","a":true,"ex":"警察官の指示には従う。","chapter":1,"section":3,"concept":"original-91"},{"id":92,"topic":"踏切","fig":"railsig","q":"踏切を通過しようとするときは直前で一時停止しなければならないが、信号機があり青色の灯火を表示している場合は、一時停止せず安全を確かめて通過できる。","a":true,"ex":"青信号の踏切は、安全を確かめれば一時停止不要。","chapter":6,"section":1,"concept":"merged-1"},{"id":93,"topic":"標識","fig":"vehicles","q":"図の標識がある道路では、自動車は進入してはならないが、自転車は進入してよい。","a":false,"ex":"自転車も「車両」なので進入できない。","chapter":1,"section":2,"concept":"merged-13"},{"id":190,"topic":"運転者の心得","fig":"naurinsa","q":"車の内輪差とは、曲がるとき後輪より前輪が内側を通ることをいう。","a":false,"ex":"逆。前輪より「後輪」が内側を通ることを内輪差という。","chapter":5,"section":7,"concept":"original-190"},{"id":191,"topic":"信号","fig":"arrowsig","q":"赤色の灯火と黄色の灯火の矢印が表示されている信号で、路線バスは矢印の方向に進むことができる。","a":false,"ex":"黄色の矢印は路面電車専用。路線バスも進めない。","chapter":1,"section":2,"concept":"original-191"},{"id":192,"topic":"免許制度","fig":"licenses","q":"大型自動二輪の免許を持っている者は、大型自動車の運転はできないが、大型免許を持っていれば大型自動二輪は運転できる。","a":false,"ex":"大型免許では大型・中型・準中型・普通自動車と、小型特殊・一般原付を運転できます。大型自動二輪を運転するには、対応する二輪免許が必要です。","chapter":4,"section":2,"concept":"original-192"},{"id":193,"topic":"通行の基本","fig":"buslane","q":"路線バス等の専用通行帯は、原動機付自転車は通行することができない。","a":false,"ex":"専用通行帯でも、原付・小型特殊・軽車両は通れる。","chapter":5,"section":2,"concept":"original-193"},{"id":194,"topic":"追い越し","fig":"leftpass","q":"車両通行帯のないトンネルでは、追い越しのため進路を変えたり、前車の側方を通過したりしてはならない。","a":true,"ex":"これは「追い越し禁止」を法律の言葉で書いた文。「追い越しのため」が「側方を通過」にもかかっている。","chapter":5,"section":6,"concept":"merged-24"},{"id":195,"topic":"安全地帯","fig":"safety3","q":"車は、やむを得ないときは安全地帯を通行してもよい。","a":false,"ex":"安全地帯には、どんな場合でも入ってはいけない。「やむを得ないとき」の例外はない。","chapter":5,"section":2,"concept":"original-195"},{"id":196,"topic":"免許制度","fig":"licenses","q":"大型免許では、大型特殊自動車を運転することができる。","a":false,"ex":"大型特殊自動車には大型特殊免許が必要。大型免許で運転できるのは大型・中型・準中型・普通・小型特殊・原付。","chapter":4,"section":2,"concept":"merged-196"},{"id":197,"topic":"合図","fig":"lanes","q":"前の車が右左折や進路を変えるため合図をしているときは、どんな場合であっても、その進路変更を妨げてはならない。","a":false,"ex":"急ブレーキや急ハンドルで避けなければならない場合は、そのまま進める。「どんな場合でも」が引っかけ。","chapter":5,"section":7,"concept":"original-197"},{"id":198,"topic":"信号","fig":"signals","q":"交差点で、対面する信号が青色を表示しているときは、自動車、一般原動機付自転車（二段階右折の交差点を除く）は、ともに直進、左折、右折することができる。","a":true,"ex":"青信号では、自動車も原付も直進・左折・右折できる。原付が直接右折できないのは二段階右折の交差点だけで、問題文はそれを除いている。","chapter":1,"section":2,"concept":"original-198"},{"id":199,"topic":"信号","fig":"stoppos","q":"交差点以外で横断歩道などがないところに信号機があるときの停止位置は、信号機の1m手前である。","a":false,"ex":"信号機の直前で止まる。「1m手前」は警察官の手信号で止まるとき。","chapter":1,"section":2,"concept":"original-199"},{"id":301,"topic":"路面電車","fig":"tracks","q":"「軌道敷内通行可」の標識により、路面電車の軌道敷内を通行している車両は、後方から路面電車が近づいてきたときは、速やかに軌道敷内を出るか、十分な距離を保たなければならない。","a":true,"ex":"路面電車の進行を妨げないよう、速やかに出るか十分な距離を保つ。","src":"練習問題1 問1","chapter":5,"section":2,"concept":"original-301","practiceSet":1},{"id":302,"topic":"路面電車","fig":"tracks","q":"路面電車の軌道敷内は、路面電車が通っていないときは、車両で通行してよい。","a":false,"ex":"軌道敷内は原則通行禁止。右左折・横断・転回や標識で認められた場合などに限られる。","src":"練習問題1 問2","chapter":5,"section":2,"concept":"merged-86","practiceSet":1},{"id":303,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道に近づいたところ、横断歩道の直前に停止している車両があったが、横断しようとしている人がいなかったので徐行して進行した。","a":false,"ex":"停止車両の側方を通って前方に出る前に、必ず一時停止しなければならない。","src":"練習問題1 問3","chapter":5,"section":3,"concept":"merged-136","practiceSet":1},{"id":304,"topic":"追い越し","fig":"pass","q":"交差点とその手前から30メートル以内の場所では、優先道路を通行しているときは、自動車や原動機付自転車を追い越すことができる。","a":true,"ex":"交差点とその手前30m以内は追越し禁止だが、優先道路を通行しているときは例外。","src":"練習問題1 問4","chapter":5,"section":6,"concept":"merged-11","practiceSet":1},{"id":305,"topic":"標識","fig":"closesigns","q":"この標識のある道路では、自動車と一般原動機付自転車は通行できない。","a":true,"ex":"自動車と一般原動機付自転車の通行止めを示す標識（車両組合せ通行止め）。この標識だけでは、特定小型原動機付自転車の通行は禁止されない。","src":"練習問題1 問5","chapter":1,"section":2,"concept":"original-305","practiceSet":1},{"id":306,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道付近に歩行者がいる場合においては、横断歩道の手前（停止線があるときには、その手前）で停止できるように速度を落として進まなければならない。","a":true,"ex":"歩行者がいないことが明らかな場合を除き、停止できる速度で進む。","src":"練習問題1 問6","chapter":5,"section":3,"concept":"merged-18","practiceSet":1},{"id":307,"topic":"標識","fig":"signs","q":"この標識のある道路では、車両は横断だけでなく、転回も禁止されている。","a":false,"ex":"「車両横断禁止」の標識。車両の横断を禁止する（道路外の施設などに出入りするための左折を伴う横断は除く）。この標識自体は転回を禁止しない。","src":"練習問題1 問7","chapter":1,"section":2,"concept":"original-307","practiceSet":1},{"id":308,"topic":"停止距離","fig":"distance","q":"車両に重い荷物を積んでいる場合は、車両の制動距離が長くなる。","a":true,"ex":"重いほど慣性が大きく、止まるまでの距離が長くなる。","src":"練習問題1 問8","chapter":5,"section":4,"concept":"original-308","practiceSet":1},{"id":309,"topic":"標識","fig":"signs","q":"この標識は、付近に学校や幼稚園があるので注意が必要であることを示している。","a":false,"ex":"これは「横断歩道」の指示標識（上がとがった青い五角形に、歩行者と横断歩道のしまの絵）。学校・幼稚園等ありは黄色のひし形の警戒標識。","src":"練習問題1 問9","chapter":1,"section":2,"concept":"merged-309","practiceSet":1},{"id":310,"topic":"運転者の心得","fig":"wakaba","q":"普通免許を受けて1年を経過していない初心運転者は、できる限り初心者マークを付けて運転するようにしなければならない。","a":false,"ex":"「できる限り」ではなく、付けることが義務。","src":"練習問題1 問10","chapter":4,"section":1,"concept":"merged-63","practiceSet":1},{"id":311,"topic":"運転者の心得","fig":"","q":"速度制限や積載の制限をこえて運転することは、騒音や振動をまき散らして沿道の住民に迷惑をかけることになる。","a":true,"ex":"違反運転は交通公害の原因にもなる。","src":"練習問題1 問11","chapter":null,"section":5,"concept":"original-311","practiceSet":1},{"id":312,"topic":"信号","fig":"signals","q":"信号のある交差点では、前方の信号に従わなければならず、横の信号が赤になったからといって発進してはならない。","a":true,"ex":"見るべきは自分の前方の信号。","src":"練習問題1 問12","chapter":1,"section":2,"concept":"original-312","practiceSet":1},{"id":313,"topic":"標識","fig":"signs","q":"この標識は、その他の危険を示す標識である。","a":true,"ex":"黄色ひし形に「！」は「その他の危険」の警戒標識。","src":"練習問題1 問13","chapter":1,"section":2,"concept":"original-313","practiceSet":1},{"id":314,"topic":"標識","fig":"signs","q":"交差点の手前で図の標識がある場合は、自分の通行している道路が「優先道路」であることを示している。","a":true,"ex":"「優先道路」の指示標識。","src":"練習問題1 問14","chapter":1,"section":2,"concept":"original-314","practiceSet":1},{"id":315,"topic":"標識","fig":"closesigns","q":"この標識では、二輪の自動車以外の自動車は通行できない。","a":true,"ex":"「二輪の自動車以外の自動車通行止め」の標識。","src":"練習問題1 問15","chapter":1,"section":2,"concept":"merged-68","practiceSet":1},{"id":316,"topic":"標識","fig":"signs","q":"この標識は、転回禁止区間内であることを示している。","a":true,"ex":"補助標識の両方向の矢印は「区間内」を示す。","src":"練習問題1 問16","chapter":1,"section":2,"concept":"original-316","practiceSet":1},{"id":317,"topic":"標識","fig":"signs","q":"この標識は、最大積載量が5.5トンを超える車両の通行が禁止されることを示している。","a":false,"ex":"「重量制限」の標識で、総重量（車＋人＋荷物）が5.5tを超える車両が通行禁止。","src":"練習問題1 問17","chapter":1,"section":2,"concept":"original-317","practiceSet":1},{"id":318,"topic":"標識","fig":"signs","q":"この標識は、この先が行き止まりとなっていることを示している。","a":false,"ex":"「幅員減少」の警戒標識。この先で道幅が狭くなる。","src":"練習問題1 問18","chapter":1,"section":2,"concept":"original-318","practiceSet":1},{"id":319,"topic":"手信号","fig":"policeorder","q":"「通行止め」の標識があるところで、交通整理中の警察官が「進め」の手信号をしたが、標識の方が優先するので、警察官の手信号に従わなかった。","a":false,"ex":"警察官の手信号は標識・信号より優先する。","src":"練習問題1 問19","chapter":1,"section":3,"concept":"original-319","practiceSet":1},{"id":320,"topic":"通行の基本","fig":"keepleft","q":"道路に面した場所に出入りするために、歩道や路側帯を横切るときは、歩行者がいたら徐行して通らなければならない。","a":false,"ex":"歩行者の有無にかかわらず、その直前で一時停止しなければならない。","src":"練習問題1 問20","chapter":5,"section":2,"concept":"original-320","practiceSet":1},{"id":321,"topic":"運転者の心得","fig":"","q":"運転者に過積載（積載物の重量の制限を超えて物を積むこと。）をして車を運転することを求めたり、過積載となるような物を売り渡したり、引き渡したりしてはならない。","a":true,"ex":"荷主等にも過積載をさせない義務がある。","src":"練習問題1 問21","chapter":1,"section":4,"concept":"original-321","practiceSet":1},{"id":322,"topic":"運転者の心得","fig":"wakaba","q":"初心運転者（普通免許を受けて1年を経過していない者）が普通乗用車を運転するときは、「初心者マーク」を定められた位置に付けなければならないが、普通貨物車を運転するときは、付けなくてもよい。","a":false,"ex":"普通自動車であれば乗用・貨物を問わず表示が必要。","src":"練習問題1 問22","chapter":4,"section":1,"concept":"merged-63","practiceSet":1},{"id":323,"topic":"運転者の心得","fig":"","q":"普通自動車免許を受けた者で70歳以上のものは、普通自動車の前面及び後面に高齢者マークを付けて普通自動車を運転するように努めなければならない。","a":true,"ex":"70歳以上で、加齢による身体機能の低下が運転に影響するおそれがあるときは、高齢者マークを付ける努力義務がある。（多くの問題集では○。厳密には「影響するおそれがあるとき」という条件つき）","src":"練習問題1 問23","chapter":4,"section":1,"concept":"original-323","practiceSet":1},{"id":324,"topic":"免許制度","fig":"karimen","q":"普通自動車仮運転免許を受けた者が、練習のため普通自動車を運転するときは、その車を運転することのできる第二種運転免許を受けている者又は第一種運転免許を受けていた期間が通算して3年以上の者等を横に乗せ、その指導を受けながら運転しなければならない。","a":true,"ex":"仮免練習時の同乗者の条件どおり。","src":"練習問題1 問24","chapter":4,"section":2,"concept":"merged-178","practiceSet":1},{"id":325,"topic":"緊急自動車","fig":"emergency","q":"交差点内を通行中、緊急自動車が近づいてきたので、その場で一時停止した。","a":false,"ex":"交差点を避け、道路の左側に寄って一時停止する。","src":"練習問題1 問25","chapter":5,"section":2,"concept":"merged-17","practiceSet":1},{"id":326,"topic":"発進","fig":"timing2","q":"方向指示器などによって発進の合図をし、もう一度バックミラーなどで前後左右の安全を確かめてから発進する。","a":true,"ex":"合図の後、再度安全確認してから発進する。","src":"練習問題1 問26","chapter":5,"section":1,"concept":"merged-221","practiceSet":1},{"id":327,"topic":"運転者の心得","fig":"seatbelt","q":"チャイルドシートは、その選択や使用方法を誤ると、効果がなくなるばかりか、逆に被害を受けるおそれがある。","a":true,"ex":"体格に合ったものを正しく取り付ける。","src":"練習問題1 問27","chapter":5,"section":1,"concept":"original-327","practiceSet":1},{"id":328,"topic":"通行の基本","fig":"oneway","q":"一方通行の道路では、道路の中央から右の部分も通行することができる。","a":true,"ex":"一方通行路は対向車がないため、右側部分も通行できる。","src":"練習問題1 問28","chapter":5,"section":2,"concept":"merged-41","practiceSet":1},{"id":329,"topic":"交差点","fig":"yield","q":"交通整理の行われていない同じような道幅の交差点で同時に入る場合は、右方の車が優先する。","a":false,"ex":"左方から来る車が優先（左方優先）。","src":"練習問題1 問29","chapter":5,"section":7,"concept":"merged-156","practiceSet":1},{"id":330,"topic":"標識","fig":"signs","q":"この標識は、危険防止のため歩行者の通行を禁止するものであるから、自動車は通行することができる。","a":false,"ex":"「通行止め」の標識。歩行者・車両・路面電車のすべてが通行できない。","src":"練習問題1 問30","chapter":1,"section":2,"concept":"merged-50","practiceSet":1},{"id":331,"topic":"安全地帯","fig":"safety3","q":"安全地帯のそばを通過しようとしたとき、安全地帯に歩行者がいたので徐行した。","a":true,"ex":"安全地帯に歩行者がいるときは徐行する。","src":"練習問題1 問31","chapter":5,"section":3,"concept":"merged-331","practiceSet":1},{"id":332,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道又は自転車横断帯やその手前で停止している車があるときには、そのそばを通って前方に出る前に一時停止をしなければならない。","a":true,"ex":"問3と同じルール。前に出る前に一時停止。","src":"練習問題1 問32","chapter":5,"section":3,"concept":"merged-136","practiceSet":1},{"id":333,"topic":"踏切","fig":"railway","q":"踏切りは危険な場所なので踏切り内では、必ず徐行しなければならない。","a":false,"ex":"踏切内に徐行義務はない。エンスト防止のため変速せず、すみやかに通過する。","src":"練習問題1 問33","chapter":6,"section":1,"concept":"original-333","practiceSet":1},{"id":334,"topic":"速度","fig":"speed","q":"標識などで、最高速度が20キロメートルと指定されていても、交通量の少ないときは、その速度を超えて運転してもよい。","a":false,"ex":"指定された最高速度は交通量に関係なく守る。","src":"練習問題1 問34","chapter":5,"section":4,"concept":"merged-29","practiceSet":1},{"id":335,"topic":"運転者の心得","fig":"","q":"ブレーキは、むやみに使わないで、なるべくアクセルの操作で徐々に速度を落としてから止まるようにするとよい。","a":true,"ex":"アクセルを戻してエンジンブレーキで減速してから止まる。ただし、ABS付きの車で緊急ブレーキをかけるときは、数回に分けず強く踏み続ける。","src":"練習問題1 問35","chapter":5,"section":4,"concept":"original-335","practiceSet":1},{"id":336,"topic":"停止距離","fig":"stop60","q":"路面が雨にぬれ、タイヤがすり減っている場合の停止距離は、乾燥路面で、タイヤの状態が良い場合に比べて2倍程度にのびることがある。","a":true,"ex":"条件が悪いと停止距離は2倍程度にのびる。","src":"練習問題1 問36","chapter":5,"section":4,"concept":"merged-148","practiceSet":1},{"id":337,"topic":"合図","fig":"timing2","q":"車が停止するときの合図の時期は、停止しようとするときである。","a":true,"ex":"徐行・停止の合図は、そうしようとするとき。","src":"練習問題1 問37","chapter":5,"section":5,"concept":"original-337","practiceSet":1},{"id":338,"topic":"警音器","fig":"horn","q":"見通しのきかない交差点は、「警笛区間」の標識のある区間以外であっても、常に警音器を鳴らさなければならない。","a":false,"ex":"見通しのきかない交差点で常に鳴らす義務はない。警笛区間内の見通しのきかない交差点などや、「警笛鳴らせ」の標識がある場所では鳴らす義務がある。危険を避けるためやむを得ない場合にも鳴らせる。","src":"練習問題1 問38","chapter":5,"section":5,"concept":"original-338","practiceSet":1},{"id":339,"topic":"進路変更","fig":"lanes","q":"この図のように、交差点の手前で車両通行帯が黄の線で区画されているところでは、後方や側方の安全を確認できれば、危険がないので右左折のため進路変更してもよい。","a":false,"ex":"黄色の線は進路変更禁止。右左折のためでも越えてはいけない。","src":"練習問題1 問39","chapter":5,"section":5,"concept":"merged-224","practiceSet":1},{"id":340,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道や自転車横断帯に近づいたとき、横断する人がいるかいないか明らかでなかったので徐行した。","a":true,"ex":"横断する人がいないことが明らかでなければ、横断歩道の手前で停止できる速度で進む。徐行はこれを満たす。","src":"練習問題1 問40","chapter":5,"section":3,"concept":"merged-18","practiceSet":1},{"id":341,"topic":"追い越し","fig":"leftpass","q":"前の車が右へ進路を変えようとしているときは、小回りのきく二輪車であっても、これを右側から追い越してはならない。","a":true,"ex":"前車が右へ進路変更しようとしているときの右側からの追越しは禁止。","src":"練習問題1 問41","chapter":5,"section":6,"concept":"merged-341","practiceSet":1},{"id":342,"topic":"追い越し","fig":"leftpass","q":"前の車を追い越すときは、前の車が右折のため道路の中央（一方通行の道路では右端）に寄っている場合を除き、その右側を通行しなければならない。","a":true,"ex":"追越しは原則右側から。","src":"練習問題1 問42","chapter":5,"section":6,"concept":"merged-159","practiceSet":1},{"id":343,"topic":"追い越し","fig":"","q":"雨でぬれた道路では、路面が滑りやすく、二輪車が追越しのために急ハンドルや急加速をすると、路外に逸脱したり転倒するなどの危険が予測されるので、二輪車による追越しはできるだけ避け、前方の車の流れに従って運転するのが安全である。","a":true,"ex":"雨天時の二輪車の追越しは危険。","src":"練習問題1 問43","chapter":null,"section":3,"concept":"original-343","practiceSet":1},{"id":344,"topic":"合図","fig":"timing2","q":"後退の合図は、後退しようとする約3秒前に行う。","a":false,"ex":"後退の合図は、後退しようとするとき。","src":"練習問題1 問44","chapter":5,"section":5,"concept":"merged-55","practiceSet":1},{"id":345,"topic":"交差点","fig":"turnway","q":"一方通行の道路から前方の交差点を左折するときは、できるだけ道路の左端に寄り、交差点の側端に沿って徐行しながら通行しなければならない。","a":true,"ex":"左折は一方通行でも左端に寄る（右折の場合は右端）。","src":"練習問題1 問45","chapter":5,"section":7,"concept":"merged-150","practiceSet":1},{"id":346,"topic":"標識・標示","fig":"zones","q":"警察署や消防署などの前に停止禁止部分の標示がなされていても、それは、緊急時の標示であるから、緊急時以外であれば、標示部分に入って停止してもかまわない。","a":false,"ex":"停止禁止部分では、緊急時以外でも停止してはならない。前方の渋滞などで、その部分に入ると停止するおそれがある場合は、その部分に入ってはいけない。","src":"練習問題1 問46","chapter":5,"section":7,"concept":"merged-157","practiceSet":1},{"id":347,"topic":"AT車","fig":"atgear","q":"オートマチック車のエンジン始動直後は、エンジンの回転数が高いので、ブレーキペダルをしっかり踏んで操作しないと急発進する危険性がある。","a":true,"ex":"始動直後はクリープ現象が強い。","src":"練習問題1 問47","chapter":5,"section":9,"concept":"merged-216","practiceSet":1},{"id":348,"topic":"AT車","fig":"atgear","q":"オートマチック車で発進のためチェンジレバーを操作するときは、アクセルペダルから足を離してさえいれば、ハンドブレーキを引いたり、ブレーキペダルを踏んでおく必要はない。","a":false,"ex":"ブレーキペダルをしっかり踏んでから操作する。","src":"練習問題1 問48","chapter":5,"section":9,"concept":"merged-215","practiceSet":1},{"id":349,"topic":"AT車","fig":"atgear","q":"オートマチック車を高速で運転中、一気にチェンジレバーをL（又は1）に入れると、急激なエンジンブレーキがかかって、スピンすることがあり交通事故の原因となる。","a":true,"ex":"高速からの急なシフトダウンは危険。","src":"練習問題1 問49","chapter":5,"section":9,"concept":"original-349","practiceSet":1},{"id":350,"topic":"携帯電話","fig":"phone","q":"自動車を運転中、カーナビゲーション装置を注視してはならないが、携帯電話の呼び出し音が鳴ったときに画面に表示された発信元を注視する程度のことであればしてもよい。","a":false,"ex":"携帯電話の画面を注視することも禁止。","src":"練習問題1 問50","chapter":5,"section":1,"concept":"merged-2","practiceSet":1},{"id":351,"topic":"徐行","fig":"slowplaces","q":"徐行とはエンジンブレーキをかけながら徐々に速度を落としながら進むことをいう。","a":false,"ex":"徐行とは、車が直ちに停止できるような速度で進むこと。エンジンブレーキで徐々に減速することではない（時速10km以下は目安で、法律で決まった数値ではない）。","src":"練習問題2 問1","chapter":5,"section":4,"concept":"merged-141","practiceSet":2},{"id":352,"topic":"合図","fig":"handsig","q":"これは、左折又は同じ方向に進行しながら進路を左方へ変えるときの合図である。","a":false,"ex":"図は右腕を車外に出して水平に伸ばす合図で、右折・転回、または右へ進路変更するときの合図。左折・左への進路変更は、右腕を車外に出してひじを垂直に上に曲げる（または左腕を水平に伸ばす）。","src":"練習問題2 問2","chapter":5,"section":5,"concept":"merged-185","practiceSet":2},{"id":353,"topic":"標識","fig":"signs","q":"この標識は、歩行者専用道路であることを示している。","a":false,"ex":"上がとがった青い五角形に歩行者としまの絵は「横断歩道」の指示標識。歩行者専用は、青い丸に大人と子どもの絵の標識。","src":"練習問題2 問3","chapter":1,"section":2,"concept":"merged-309","practiceSet":2},{"id":354,"topic":"免許制度","fig":"licenses","q":"大型免許を受けている者は、大型自動車のほか、中型自動車、普通自動車、小型特殊自動車、原動機付自転車を運転することができる。","a":true,"ex":"大型免許で、中型・準中型・普通・小型特殊自動車と原動機付自転車も運転できる。","src":"練習問題2 問4","chapter":4,"section":2,"concept":"original-354","practiceSet":2},{"id":355,"topic":"緊急自動車","fig":"emergency","q":"交差点付近で緊急自動車が近づいていたので、交差点内の左端に寄って進路をゆずった。","a":false,"ex":"交差点やその付近では、交差点を避けて道路の左側に寄り、一時停止する。交差点内に入って寄るのではない。","src":"練習問題2 問5","chapter":5,"section":2,"concept":"merged-17","practiceSet":2},{"id":356,"topic":"免許制度","fig":"licenses","q":"代行運転自動車である普通自動車を運転しようとする場合には、第二種運転免許が必要である。","a":true,"ex":"代行運転自動車として運転するときは、第二種運転免許が必要。","src":"練習問題2 問6","chapter":4,"section":2,"concept":"original-356","practiceSet":2},{"id":357,"topic":"通行の基本","fig":"lanes","q":"車両通行帯があり、標識や標示により通行区分が指定されていない道路において、急いでいたので最も右側の車両通行帯を通行し続けた。","a":false,"ex":"片側2車線では左側の通行帯を、3車線以上では最も右側以外の通行帯を速度に応じて通行する。最も右側の通行帯は追越しなどのためにあけておき、急いでいても通行し続けてはいけない。","src":"練習問題2 問7","chapter":5,"section":2,"concept":"merged-129","practiceSet":2},{"id":358,"topic":"通行の基本","fig":"centerline","q":"道路の左側部分の交通が混雑しているときは、中央線から右側部分を通行することができる。","a":false,"ex":"左側が混雑していることは、右側部分を通行できる理由にならない。","src":"練習問題2 問8","chapter":5,"section":2,"concept":"original-358","practiceSet":2},{"id":359,"topic":"交差点","fig":"","q":"この標示により進行する方向の通行区分が指定されている交差点で、二段階右折する原動機付自転車は、右折の指定のある最も右の車両通行帯を通行しなければならない。","a":false,"ex":"二段階右折する一般原付は右折レーンに入らず、最も左側の車両通行帯を通行して交差点の向こう側まで進み、向きを変えて待つ。","src":"練習問題2 問9","chapter":5,"section":7,"concept":"original-359","practiceSet":2},{"id":360,"topic":"標識","fig":"closesigns","q":"この標識のある道路では、二輪の自動車や原動機付自転車は通行できない。","a":false,"ex":"「二輪の自動車以外の自動車通行止め」の標識。二輪の自動車や原付は通行できる。","src":"練習問題2 問10","chapter":1,"section":2,"concept":"merged-68","practiceSet":2},{"id":361,"topic":"信号","fig":"signals","q":"40キロメートル毎時で走行中、停止線から10メートル手前で信号機の灯火が青色から黄色に変わったがそのまま進行した。","a":true,"ex":"時速40kmでは、停止線の10m手前から安全に停止できない。黄色でも停止位置で安全に停止できないときは、そのまま進める。","src":"練習問題2 問11","chapter":1,"section":2,"concept":"merged-111","practiceSet":2},{"id":362,"topic":"信号","fig":"signals","q":"この信号に対面する車や路面電車は、停止位置で一時停止し、安全確認をして進むことができる。","a":true,"ex":"赤色の灯火の点滅では、停止位置で一時停止し、安全を確認してから進める。","src":"練習問題2 問12","chapter":1,"section":2,"concept":"merged-40","practiceSet":2},{"id":363,"topic":"標識","fig":"signs","q":"この標識は、歩行者だけの通行のため設けられた道路を示している。","a":true,"ex":"「歩行者専用」の標識。","src":"練習問題2 問13","chapter":1,"section":2,"concept":"original-363","practiceSet":2},{"id":364,"topic":"標識","fig":"closesigns","q":"この標識は、普通乗用自動車の通行のみを禁止している。","a":false,"ex":"「二輪の自動車以外の自動車通行止め」の標識。普通乗用車だけでなく、二輪を除くすべての自動車が通行できない。","src":"練習問題2 問14","chapter":1,"section":2,"concept":"merged-68","practiceSet":2},{"id":365,"topic":"標識","fig":"signs","q":"この標識は、追越し禁止を示している。","a":false,"ex":"「転回禁止」の標識。","src":"練習問題2 問15","chapter":1,"section":2,"concept":"merged-73","practiceSet":2},{"id":366,"topic":"標識","fig":"closesigns","q":"図の道路標識は、自動車と原動機付自転車の通行止めをあらわしている。","a":true,"ex":"車両（組合せ）通行止めの標識。上の絵は自動車、下の絵は原付で、自動車と原付は通行できない。","src":"練習問題2 問16","chapter":1,"section":2,"concept":"original-366","practiceSet":2},{"id":367,"topic":"標識","fig":"signs","q":"この標識は、横断歩道と自転車横断帯であることを示している。","a":true,"ex":"「横断歩道・自転車横断帯」の標識。","src":"練習問題2 問17","chapter":1,"section":2,"concept":"original-367","practiceSet":2},{"id":368,"topic":"標識・標示","fig":"zones","q":"この標示は、車両の立ち入り禁止部分であることを示している。","a":true,"ex":"「立入り禁止部分」の標示。車はこの中に入ってはいけない。","src":"練習問題2 問18","chapter":1,"section":2,"concept":"original-368","practiceSet":2},{"id":369,"topic":"手信号","fig":"stoppos","q":"警察官が手信号により、交差点以外で横断歩道などのないところで両腕を横に水平に上げているときは対面する車は、その警察官の1メートル手前のところで停止しなければならない。","a":true,"ex":"交差点以外で横断歩道などがないところでは、警察官の1m手前で停止する。","src":"練習問題2 問19","chapter":1,"section":3,"concept":"original-369","practiceSet":2},{"id":370,"topic":"手信号","fig":"police","q":"この図のような警察官の手信号は、矢印の方向に対しては、信号機の信号の黄と同じ意味である。","a":false,"ex":"腕を横に水平に上げているときは、矢印の方向（警察官の横から向かう交通）は青、警察官の正面・背中側から向かう交通は赤と同じ意味。腕を垂直に上げると、矢印の方向が黄になり、正面・背中側は赤のまま。","src":"練習問題2 問20","chapter":1,"section":3,"concept":"merged-80","practiceSet":2},{"id":371,"topic":"標識","fig":"signs","q":"図の標識は、センターラインの無いところの道路の中心を表しているものである。","a":false,"ex":"「中央線」の標識は、道路の中央や中央線の位置を示す。「センターラインのない道路の、幅の真ん中」を示す標識ではない。","src":"練習問題2 問21","chapter":1,"section":2,"concept":"original-371","practiceSet":2},{"id":372,"topic":"免許制度","fig":"licenses","q":"大型免許を受けていれば、大型特殊自動車を運転することができる。","a":false,"ex":"大型特殊自動車を運転するには、大型特殊免許が必要。","src":"練習問題2 問22","chapter":4,"section":2,"concept":"merged-196","practiceSet":2},{"id":373,"topic":"免許制度","fig":"licenses","q":"原付免許では、エンジンの総排気量が50ccを超える二輪の自動車の運転はすることができない。","a":true,"ex":"「二輪の自動車」は法律上の分類で、原付免許では運転できない。ただし2025年4月から、総排気量125cc以下・最高出力4.0kW以下の新基準原付は「原動機付自転車」に分類されるため、「50ccを超える二輪車はすべて原付免許で運転できない」と覚えるのは誤り。","src":"練習問題2 問23","chapter":4,"section":2,"concept":"original-373","practiceSet":2},{"id":374,"topic":"通行の基本","fig":"buslane","q":"路線バスなど優先通行帯は、路線バスなどのほかに軽車両だけが通行できる。","a":false,"ex":"自動車も通行できるが、路線バスなどが近づいてきたら、すみやかにその通行帯から出なければならない。最も左の通行帯を通る小型特殊・原付・軽車両は、バスが近づいても出る必要はない。","src":"練習問題2 問24","chapter":5,"section":2,"concept":"original-374","practiceSet":2},{"id":375,"topic":"携帯電話","fig":"phone","q":"自動車を運転中、行き先がわからなくなったので、備え付けのカーナビゲーションを注視しながら走行した。","a":false,"ex":"走行中にカーナビの画面を注視してはいけない。確認するときは安全な場所に停止する。","src":"練習問題2 問25","chapter":5,"section":1,"concept":"merged-2","practiceSet":2},{"id":376,"topic":"追い越し","fig":"centerline","q":"道路の左側部分の幅が6メートル以上あれば、右側の部分を通って追い越しても差し支えない。","a":false,"ex":"左側部分の幅が6m以上ある道路では、右側部分にはみ出して追越しをしてはいけない。","src":"練習問題2 問26","chapter":5,"section":6,"concept":"merged-227","practiceSet":2},{"id":377,"topic":"緊急自動車","fig":"emergency","q":"交差点の付近で緊急自動車が近づいてきたので、交差点の片すみに寄って進路をゆずった。","a":false,"ex":"交差点やその付近では、交差点を避けて道路の左側に寄り、一時停止する。","src":"練習問題2 問27","chapter":5,"section":2,"concept":"merged-17","practiceSet":2},{"id":378,"topic":"交差点","fig":"","q":"車両通行帯のある2車線道路の交差点では、事故防止のため、原動機付自転車は必ず二段階右折をしなければならない。","a":false,"ex":"一般原付が二段階右折しなければならないのは、交通整理が行われている片側3車線以上の交差点や、標識で指定された交差点。（特定小型原付はいつでも二段階右折）","src":"練習問題2 問28","chapter":5,"section":7,"concept":"original-378","practiceSet":2},{"id":379,"topic":"標識・標示","fig":"zones","q":"この標示の中に車は入ってはならない。","a":true,"ex":"「安全地帯」の標示。車は入ってはいけない。","src":"練習問題2 問29","chapter":1,"section":2,"concept":"original-379","practiceSet":2},{"id":380,"topic":"安全地帯","fig":"safety3","q":"安全地帯のそばを通るときは、歩行者がいなくても徐行しなければならない。","a":false,"ex":"安全地帯に歩行者がいるときは徐行する。ただし、停留所で停車中の路面電車の横を、安全地帯があるため通過できる場合は、歩行者がいなくても徐行する。","src":"練習問題2 問30","chapter":5,"section":3,"concept":"merged-331","practiceSet":2},{"id":381,"topic":"歩行者保護","fig":"pedcross","q":"車の運転者は、横断歩道に歩行者がいなくても徐行して通過しなければならない。","a":false,"ex":"横断する人がいないことが明らかなら、横断歩道という理由だけで徐行する義務はない。人がいるか分からないときは、横断歩道の手前で停止できる速度に落とす。","src":"練習問題2 問31","chapter":5,"section":3,"concept":"merged-18","practiceSet":2},{"id":382,"topic":"歩行者保護","fig":"protect","q":"車椅子で通行している人のそばを通るときは、一時停止か徐行をしなければならない。","a":true,"ex":"車椅子の人や、白や黄色のつえを持った人などのそばを通るときは、一時停止か徐行をする。","src":"練習問題2 問32","chapter":5,"section":3,"concept":"original-382","practiceSet":2},{"id":383,"topic":"踏切","fig":"railway","q":"踏切を通過するとき、前の車が一時停止し安全を確かめたので、続いて通過した。","a":false,"ex":"前の車が一時停止していても、自分も停止位置で一時停止し、安全を確かめなければならない。","src":"練習問題2 問33","chapter":6,"section":1,"concept":"original-383","practiceSet":2},{"id":384,"topic":"停止距離","fig":"stop60","q":"ぬれたアスファルト道路や雪道では、路面がよく滑り、タイヤと路面の摩擦抵抗が大きくなるので、制動距離が短くなる。","a":false,"ex":"摩擦抵抗は小さくなるので、制動距離は長くなる。","src":"練習問題2 問34","chapter":5,"section":4,"concept":"merged-148","practiceSet":2},{"id":385,"topic":"運転者の心得","fig":"","q":"ブレーキを掛けるときは、最初はできるだけ軽く踏み込み、それから必要な強さまで徐々に踏み込むのがよい。","a":true,"ex":"通常のブレーキ操作の基本。ただし、ABS付きの車で緊急ブレーキをかけるときは、強く踏み続ける。","src":"練習問題2 問35","chapter":5,"section":4,"concept":"original-385","practiceSet":2},{"id":386,"topic":"徐行","fig":"slowplaces","q":"交通整理の行われていない、見通しの悪い交差点であっても、他の車がなければ徐行しないで通過することができる。","a":false,"ex":"交通整理の行われていない見通しの悪い交差点では、優先道路を通行している場合などを除き、徐行しなければならない。","src":"練習問題2 問36","chapter":5,"section":4,"concept":"original-386","practiceSet":2},{"id":387,"topic":"徐行","fig":"slowplaces","q":"上り坂は、徐行の場所である。","a":false,"ex":"徐行すべき場所は「上り坂の頂上付近」と「こう配の急な下り坂」。上り坂そのものは徐行場所ではない。","src":"練習問題2 問37","chapter":5,"section":4,"concept":"merged-144","practiceSet":2},{"id":388,"topic":"合図","fig":"timing","q":"車を運転中、同じ方向に進行しながら進路を左方に変えるときの合図の時期は、ハンドルを切り始めようとするときである。","a":false,"ex":"進路変更の合図は、進路を変えようとする約3秒前に行う。","src":"練習問題2 問38","chapter":5,"section":5,"concept":"merged-35","practiceSet":2},{"id":389,"topic":"合図","fig":"handsig","q":"後退するときの合図の方法は、後退灯をつけるか、腕を車の外に出して斜め下にのばし、手のひらを後ろに向けて、その腕を前後に動かせばよい。","a":true,"ex":"後退の合図の方法として正しい。","src":"練習問題2 問39","chapter":5,"section":5,"concept":"original-389","practiceSet":2},{"id":390,"topic":"標識","fig":"signs","q":"この2つの標識のあるところでは、同時に後退も禁止されている。","a":false,"ex":"「転回禁止」と「車両横断禁止」の標識。後退は禁止されていない。","src":"練習問題2 問40","chapter":1,"section":2,"concept":"original-390","practiceSet":2},{"id":391,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道のない交差点やその近くを歩行者が横断しているときは、その通行を妨げてはいけません。","a":true,"ex":"横断歩道のない交差点やその付近でも、横断している歩行者の通行を妨げてはいけない。","src":"練習問題2 問41","chapter":5,"section":3,"concept":"merged-239","practiceSet":2},{"id":392,"topic":"追い越し","fig":"hill","q":"上り坂の頂上付近で、大型バスの後ろについていた二輪車が、前の視界がさえぎられるのを避けるため、速度を上げてそのバスを追い越した。","a":false,"ex":"上り坂の頂上付近は追越し禁止の場所。","src":"練習問題2 問42","chapter":5,"section":6,"concept":"merged-48","practiceSet":2},{"id":393,"topic":"追い越し","fig":"passdef","q":"ほかの車に追い越されるとき、相手に追越しをするための十分な余地がない場合は、できるだけ左に寄り、進路をゆずらなければならない。","a":true,"ex":"追越しのための十分な余地がないときは、できるだけ左に寄って進路をゆずる。","src":"練習問題2 問43","chapter":5,"section":6,"concept":"merged-164","practiceSet":2},{"id":394,"topic":"追い越し","fig":"passdef","q":"追越しが終わったら、できるだけ早く追い越した車の前に進路を変えた方がよい。","a":false,"ex":"追い越した車との間に十分な車間距離がとれてから、ゆるやかに進路を戻す。","src":"練習問題2 問44","chapter":5,"section":6,"concept":"merged-250","practiceSet":2},{"id":395,"topic":"警音器","fig":"horn","q":"車両通行帯のある道路を通行中、並進していた左側の車両がいきなり進路を変更してきたので、接触をさけるため警音器を鳴らした。","a":true,"ex":"危険を避けるためやむを得ないときは、警音器を鳴らせる。","src":"練習問題2 問45","chapter":5,"section":5,"concept":"merged-170","practiceSet":2},{"id":396,"topic":"交差点","fig":"zones","q":"信号機のある交差点を通過する際、前方が混雑していたため、交差点内に入って停止すると、交差方向の車の通行を妨げるおそれがあったので、信号機の信号が青であったが交差点手前で停車した。","a":true,"ex":"信号が青でも、交差点内で止まって交差方向の通行を妨げるおそれがあるときは、交差点に入ってはいけない。","src":"練習問題2 問46","chapter":5,"section":7,"concept":"original-396","practiceSet":2},{"id":397,"topic":"交差点","fig":"yield","q":"交通整理の行われていない交差点に差し掛かったとき、ほかの車や路面電車が接近していたので、衝突事故を避けるため、速度をはやめてその交差点を通過した。","a":false,"ex":"交差する車や路面電車に注意し、安全な速度で進む。速度を上げて先に通過しようとしてはいけない。","src":"練習問題2 問47","chapter":5,"section":7,"concept":"original-397","practiceSet":2},{"id":398,"topic":"AT車","fig":"atgear","q":"オートマチック車を駐車させるときは、ブレーキペダルを踏んだままハンドブレーキを確実に掛け、チェンジレバーをPの位置に入れてからエンジンを切る。","a":true,"ex":"AT車の駐車手順として正しい。","src":"練習問題2 問48","chapter":5,"section":9,"concept":"original-398","practiceSet":2},{"id":399,"topic":"追い越し","fig":"pass","q":"前の車が右折のために右側に進路を変えようとしているときは、追越し禁止の場所でなくても追越しをしてはいけない。","a":true,"ex":"前の車が右折などのため右に進路を変えようとしているときは、追越しをしてはいけない。","src":"練習問題2 問49","chapter":5,"section":6,"concept":"merged-341","practiceSet":2},{"id":400,"topic":"AT車","fig":"atgear","q":"オートマチック車でのエンジン始動直後の走行は、エンジンの回転数が高く、アクセルペダルから足を離しただけでは十分に減速できないことがあるので注意する。","a":true,"ex":"始動直後はエンジン回転数が高く、クリープ現象も強い。","src":"練習問題2 問50","chapter":5,"section":9,"concept":"merged-216","practiceSet":2},{"id":64,"topic":"停止距離","fig":"stop60","q":"時速60kmで走行している普通乗用車の停止距離は、乾燥したアスファルト道路で約44mである。","a":true,"ex":"教本で使う条件での目安は約44mです。路面・タイヤ・車両・反応時間で変わります。車間距離を一律44mに固定する意味ではありません。","chapter":5,"section":4,"concept":"merged-61"},{"id":65,"topic":"交差点","fig":"jam2","q":"交差点で前の車が渋滞しているときは、対向車に注意していても、右側の対向車線を通って先に進んではならない。","a":true,"ex":"列の後ろで待つ。交差点内で止まりそうなら入らない。","chapter":5,"section":7,"concept":"merged-62"},{"id":66,"topic":"標識","fig":"closesigns","q":"図の標識がある道路は、普通貨物自動車も通行できない。","a":false,"ex":"通れないのは大型貨物など。普通貨物自動車は通れる。","chapter":1,"section":2,"concept":"original-66"},{"id":67,"topic":"標識","fig":"closesigns","q":"図の標識がある道路は、普通乗用車も通行できない。","a":false,"ex":"普通乗用車は通れる。","chapter":1,"section":2,"concept":"original-67"},{"id":68,"topic":"標識","fig":"closesigns","q":"図の標識がある道路は、一般原動機付自転車も通行できない。","a":false,"ex":"通れないのは二輪以外の自動車（四輪・三輪など）。自動二輪と原付は通れる。","chapter":1,"section":2,"concept":"merged-68"},{"id":69,"topic":"標識","fig":"closesigns","q":"図の標識がある道路は、普通乗用車は通行できる。","a":true,"ex":"この標識で禁止されるのは二輪の自動車と一般原付です。普通乗用車はこの標識の対象ではありません。","revised":true,"chapter":1,"section":2,"concept":"original-69"},{"id":70,"topic":"標識","fig":"noentry","q":"図の標識は、この標識がある側からの車両の進入を禁止するもので、反対側の交通まで一律に禁止するものではない。","a":true,"ex":"この標識自体は片方向からの進入を禁止します。一方通行の出口によく設けられますが、反対側の別の規制にも注意します。","chapter":1,"section":2,"concept":"merged-13"},{"id":71,"topic":"標識","fig":"vehicles","q":"図の標識がある道路には、車だけでなく歩行者も標識の側から入ってはならない。","a":false,"ex":"対象は車だけ。歩行者もダメなのは「通行止め」。","chapter":1,"section":2,"concept":"merged-13"},{"id":72,"topic":"標識","fig":"slash","q":"図の標識は、「駐車禁止」を表している。","a":false,"ex":"×は駐停車禁止。1本が駐車禁止。","chapter":1,"section":2,"concept":"merged-26"},{"id":73,"topic":"標識","fig":"slash","q":"図の標識は、「転回禁止」を表している。","a":true,"ex":"Uターン禁止の標識。","chapter":1,"section":2,"concept":"merged-73"},{"id":74,"topic":"信号","fig":"arrowsig","q":"赤信号のときに表示される青色の矢印の信号は、大型自動車に対する信号なので、路線バスは矢印の方向に進めるが、二輪車は進めない。","a":false,"ex":"青い矢印は大型車専用ではありません。ただし右向きの矢印では、特定小型原付・軽車両・二段階右折の一般原付は進めません。","revised":true,"chapter":1,"section":2,"concept":"original-74"},{"id":75,"topic":"信号","fig":"arrowsig","q":"右折の青色の矢印信号が表示されていても、二段階右折をする原付は右折できない。","a":true,"ex":"右向きの青矢印では、二段階右折の一般原付、特定小型原付、自転車などの軽車両は進めません。","chapter":1,"section":2,"concept":"original-75"},{"id":76,"topic":"標識","fig":"stopline","q":"図の標識があるところでは、この標識だけを理由として一時停止しなければならない。","a":false,"ex":"停止線は止まる場合の位置を示すだけ。一時停止の義務は「止まれ」。","chapter":1,"section":2,"concept":"original-76"},{"id":77,"topic":"発進","fig":"door","q":"自動車に乗ってドアを閉めるときは、半ドアを防ぐため、力強く一気に閉めるようにする。","a":false,"ex":"少し手前まで閉めて、はさまるものがないか確かめてから力を入れて閉める。","chapter":5,"section":1,"concept":"original-77"},{"id":78,"topic":"手信号","fig":"police","q":"図の警察官は腕を垂直に上げている。「あなたの車」に対しては、黄色の信号と同じ意味である。","a":true,"ex":"腕を上げる＝横は黄、前後は赤。","chapter":1,"section":3,"concept":"original-78"},{"id":79,"topic":"手信号","fig":"police","q":"図のように警察官が両腕を水平に上げているとき、正面に向かう「あなたの車」に対しては、青色の信号と同じ意味である。","a":false,"ex":"正面と背面はいつも赤。","chapter":1,"section":3,"concept":"merged-79"},{"id":80,"topic":"手信号","fig":"police","q":"図のように警察官が灯火を横に振っているとき、振られている方向に進む「あなたの車」に対しては、青色の信号と同じ意味である。","a":true,"ex":"灯火を振っている方向に進む交通が青、それと交差する交通が赤です。法令は「振っている方向」で決めています（教則の「身体の正面に平行する交通」と、ふつうは同じ方向です）。","chapter":1,"section":3,"concept":"merged-80"},{"id":81,"topic":"路面電車","fig":"tram3","q":"安全地帯のない停留所で、乗り降りする人がいなく、路面電車との間に1.5m以上の間隔がとれるときは、徐行して進むことができる。","a":true,"ex":"人が車の通り道にいないので徐行で通れる。","chapter":5,"section":3,"concept":"original-81"},{"id":82,"topic":"路面電車","fig":"tram3","q":"安全地帯のない停留所で路面電車に乗り降りする人がいるときは、人がいなくなるまで路面電車の後方で停止して待たなければならない。","a":true,"ex":"人が車道を横切るので停止して待つ。","chapter":5,"section":3,"concept":"original-82"},{"id":83,"topic":"安全地帯","fig":"safety3","q":"安全地帯に歩行者がいないときは、車は徐行すれば安全地帯の中を通行してもよい。","a":false,"ex":"車は安全地帯に入ってはいけない。","chapter":5,"section":2,"concept":"original-83"},{"id":84,"topic":"路面電車","fig":"tracks","q":"軌道敷内は通行してはならないので、右折するために横切ることもできない。","a":false,"ex":"右左折・横断・転回で横切るのはOK。","chapter":5,"section":2,"concept":"original-84"},{"id":85,"topic":"路面電車","fig":"tracks","q":"路面電車を追い越すときは、軌道が道路の左端に寄っている場合を除き、右側を通行しなければならない。","a":false,"ex":"路面電車は左側から追い越す（軌道が左端寄りなら右側）。","chapter":5,"section":6,"concept":"original-85"},{"id":100,"topic":"運転者の心得","fig":"drink","q":"酒を飲んでも、少量で酔った感じがしなければ、慎重に運転すれば違反にはならない。","a":false,"ex":"少しでも酒を飲んだら運転してはいけない。酔った感じがなくても違反。","chapter":4,"section":1,"concept":"original-100"},{"id":101,"topic":"運転者の心得","fig":"drink","q":"酒を飲んだ人がこれから運転するおそれがあると分かっていても、自分が飲酒していなければ、その人に車を貸してよい。","a":false,"ex":"飲酒運転をするおそれがある人に車を提供してはいけません。提供する側が飲酒していない場合も同じです。","chapter":4,"section":1,"concept":"original-101"},{"id":102,"topic":"運転者の心得","fig":"drink","q":"かぜ薬や花粉症の薬などを飲んで眠気を感じるときは、運転を控えるべきである。","a":true,"ex":"眠気は判断や反応を遅らせる。","chapter":4,"section":1,"concept":"original-102"},{"id":103,"topic":"携帯電話","fig":"phone","q":"携帯電話を手に持って通話してはいけないが、少し進んでは止まるような渋滞中であれば、手に持って通話してもよい。","a":false,"ex":"渋滞でも動いている間は、手に持って通話してはいけません。停止中はこの禁止規定の対象外ですが、再発進する前に使用をやめます。","chapter":5,"section":1,"concept":"merged-2"},{"id":104,"topic":"携帯電話","fig":"phone","q":"運転中は携帯電話の画面に表示された地図などを注視してはならないが、車が完全に停止しているときは見てもよい。","a":true,"ex":"停止中は、この注視の禁止規定の対象外です。走り始める前に使用をやめて、安全を確認します。","chapter":5,"section":1,"concept":"merged-2"},{"id":105,"topic":"運転者の心得","fig":"seatbelt","q":"高速道路では後部座席の同乗者にも座席ベルトを着用させなければならないが、一般道路ではその必要はない。","a":false,"ex":"後部座席のベルトも、一般道路を含むすべての道路で着用させる。","chapter":5,"section":1,"concept":"original-105"},{"id":106,"topic":"運転者の心得","fig":"seatbelt","q":"6歳未満の幼児でも、大人がひざの上でしっかり抱いていれば、チャイルドシートを使わなくてもよい。","a":false,"ex":"抱っこではダメ。6歳未満はチャイルドシートを使う（病気などやむを得ない理由がある場合を除く）。","chapter":5,"section":1,"concept":"original-106"},{"id":107,"topic":"運転者の心得","fig":"seatbelt","q":"運転者は、自分が座席ベルトを締めていれば、助手席の同乗者に座席ベルトを着用させる義務はない。","a":false,"ex":"同乗者全員に着用させる義務がある。","chapter":5,"section":1,"concept":"original-107"},{"id":108,"topic":"発進","fig":"posture","q":"シートの前後の位置は、ブレーキペダルをいっぱいに踏み込んだとき、ひざがわずかに曲がる状態に合わせる。","a":true,"ex":"足が伸びきると強く踏めない。","chapter":5,"section":1,"concept":"original-108"},{"id":109,"topic":"発進","fig":"posture","q":"ハンドルは、腕をいっぱいに伸ばし、背もたれから背中を少し離して持つのが正しい運転姿勢である。","a":false,"ex":"背中は背もたれにつけ、ハンドルを持ったときにひじが少し曲がる位置にする。","chapter":5,"section":1,"concept":"original-109"},{"id":110,"topic":"信号","fig":"signals","q":"青色の灯火の信号では、自動車も原付もすべて、交差点で直接右折することができる。","a":false,"ex":"二段階右折しなければならない原付は、青でも直接右折できない。","chapter":1,"section":2,"concept":"original-110"},{"id":111,"topic":"信号","fig":"signals","q":"黄色の灯火に変わったとき、停止位置に近づいていて安全に停止できない場合は、そのまま進むことができる。","a":true,"ex":"黄は原則停止。ただし安全に止まれないときは進める。","chapter":1,"section":2,"concept":"merged-111"},{"id":112,"topic":"信号","fig":"rightturn","q":"信号が赤色の灯火に変わっても、交差点ですでに右折している自動車は、そのまま進むことができる。","a":true,"ex":"すでに右折中の自動車は進めますが、青信号に従って進む車や路面電車の進行を妨げてはいけません。安全を確かめて速やかに交差点から出ます。","chapter":1,"section":2,"concept":"merged-43"},{"id":113,"topic":"信号","fig":"signals","q":"赤色の灯火の点滅信号の交差点では、左右の安全を確かめれば、徐行して交差点に入ることができる。","a":false,"ex":"赤の点滅は、停止位置で一時停止してから進む。徐行だけではダメ。","chapter":1,"section":2,"concept":"merged-40"},{"id":114,"topic":"信号","fig":"arrowsig","q":"赤色の灯火と同時に左向きの青色の矢印が表示されているときは、自動車は左折できるが、原付は左折できない。","a":false,"ex":"青い矢印はすべての車が対象。原付も左折できる。","chapter":1,"section":2,"concept":"original-114"},{"id":115,"topic":"信号","fig":"policeorder","q":"図のように信号機の信号と警察官の手信号が異なるときは、信号機の信号に従う。","a":false,"ex":"警察官の手信号が優先。","chapter":1,"section":3,"concept":"original-115"},{"id":116,"topic":"手信号","fig":"police","q":"図のように警察官が両腕を水平に上げているとき、正面に向かう「あなたの車」に対しては、赤色の信号と同じ意味である。","a":true,"ex":"正面と背中の方向は赤。腕の方向（横）は青。","chapter":1,"section":3,"concept":"merged-79"},{"id":117,"topic":"手信号","fig":"police","q":"図のように警察官が腕を垂直に上げているとき、正面に向かう「あなたの車」に対しては、青色の信号と同じ意味である。","a":false,"ex":"手信号では、身体の正面・背面に対面する交通は赤です。腕を垂直に上げたとき、身体の正面に平行する交通が黄です。","chapter":1,"section":3,"concept":"original-117"},{"id":118,"topic":"標識","fig":"signs","q":"図の標識がある道路では、一般原動機付自転車も時速40kmまで出すことができる。","a":false,"ex":"原付の最高速度は30km。標識が40でも原付は30kmまで。","chapter":5,"section":4,"concept":"merged-29"},{"id":119,"topic":"標識","fig":"stopline","q":"図の標識がある交差点で停止線がない場合は、交差点の中に少し入ったところで一時停止して、左右を確認する。","a":false,"ex":"停止線がなければ、交差点の直前で一時停止する。","chapter":1,"section":2,"concept":"original-119"},{"id":120,"topic":"標識","fig":"signs","q":"図のような黄色のひし形の標識は、通行の禁止や制限を表す規制標識である。","a":false,"ex":"黄色のひし形は警戒標識（この先に危険があることを知らせる）。規制標識は赤い縁の丸など。","chapter":1,"section":2,"concept":"merged-27"},{"id":121,"topic":"標識","fig":"stoppark","q":"図の標識がある場所でも、他の駐停車禁止に当たらず、運転者がすぐ運転できる状態なら、5分以内の荷物の積みおろしや人の乗り降りのために停車できる。","a":true,"ex":"駐車禁止と駐停車禁止を区別します。短時間でも客待ちや、離れてすぐ運転できない状態は駐車です。","chapter":null,"section":8,"concept":"original-121"},{"id":122,"topic":"標識","fig":"slash","q":"図の標識がある場所でも、人の乗り降りのためのわずかな時間の停車であれば、することができる。","a":false,"ex":"駐停車禁止は停車もダメ。","chapter":null,"section":8,"concept":"original-122"},{"id":123,"topic":"標識","fig":"noentry","q":"図の標識がある道路は、自動車や原付、自転車は通行できないが、歩行者は通行することができる。","a":true,"ex":"人も通れないのは文字入りの「通行止め」。","chapter":1,"section":2,"concept":"original-123"},{"id":124,"topic":"標識","fig":"oneway","q":"図の標識が示す一方通行の道路では、緊急自動車に進路を譲る場合を除き、道路の右側部分にはみ出して通行してはいけない。","a":false,"ex":"一方通行の道路は対向車がないので、右側部分も通行できる。","chapter":5,"section":2,"concept":"merged-41"},{"id":125,"topic":"追い越し","fig":"centerline","q":"中央線の白い破線自体には、追い越しのため道路の右側部分にはみ出すことを禁止する意味はない。","a":true,"ex":"白の破線自体は、追い越しのための右側はみ出しを禁止しません。ただし左側部分の幅6m未満、見通しがよい、対向車等を妨げないなどの条件があり、追い越し禁止場所ではできません。","chapter":5,"section":2,"concept":"original-125","revised":true},{"id":126,"topic":"追い越し","fig":"centerline","q":"中央線が黄色の実線の道路では、右側部分にはみ出さずに追い越しができる場合であっても、追い越しをしてはいけない。","a":false,"ex":"黄色の中央線で禁止されるのは「追い越しのための右側はみ出し」です。他の追い越し禁止に当たらず、安全を確保できれば、はみ出さない追い越しは可能です。","chapter":5,"section":2,"concept":"original-126"},{"id":127,"topic":"通行の基本","fig":"keepleft","q":"車は左側通行が原則だが、歩道や路側帯のない道路では、歩行者と同じく道路の右側を通行する。","a":false,"ex":"歩道等がない道路でも、車は原則として左側を通ります。歩行者は原則として右側端です。一方通行や工事などの例外とは別の話です。","chapter":5,"section":2,"concept":"original-127"},{"id":128,"topic":"通行の基本","fig":"keepleft","q":"道路に面した場所に出入りするため歩道を横切るときは、歩行者がいなければ徐行して横切ってよい。","a":false,"ex":"歩行者がいなくても、歩道の直前で一時停止。","chapter":5,"section":2,"concept":"original-128"},{"id":129,"topic":"通行の基本","fig":"lanes","q":"片側2車線の道路では、速度の速い車は右側の車線を通行し、そのまま右側の車線を走り続けてもよい。","a":false,"ex":"左側の車線を通る。右側は追い越しなどのためにあけておく。","chapter":5,"section":2,"concept":"merged-129"},{"id":130,"topic":"通行の基本","fig":"lanes","q":"片側3車線の道路では、一番右側の車線は追い越しなどのためにあけておき、それ以外の車線を速度に応じて通行する。","a":true,"ex":"遅い車は左寄りの車線。","chapter":5,"section":2,"concept":"merged-129"},{"id":131,"topic":"通行の基本","fig":"oneway","q":"道路工事などでやむを得ない場合は、道路の中央から右の部分にはみ出して通行することができる。","a":true,"ex":"工事などでやむを得ないときはOK。","chapter":5,"section":2,"concept":"original-131"},{"id":132,"topic":"緊急自動車","fig":"emergency","q":"交差点付近以外の場所で緊急自動車が近づいてきたときは、道路の左側に寄って一時停止しなければならない。","a":false,"ex":"交差点付近以外は、左に寄って進路を譲るだけ。一時停止が必要なのは交差点やその付近。","chapter":5,"section":2,"concept":"merged-17"},{"id":133,"topic":"緊急自動車","fig":"emergency","q":"一方通行の道路で、左に寄るとかえって緊急自動車の妨げになるときは、右に寄って進路を譲る。","a":true,"ex":"妨げになるなら右に寄る。","chapter":5,"section":2,"concept":"original-133"},{"id":134,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道に近づいたとき、横断する人がいるかいないか明らかでない場合は、手前で停止できるような速度で進む。","a":true,"ex":"分からないときは止まれる速度に。","chapter":5,"section":3,"concept":"merged-18"},{"id":135,"topic":"歩行者保護","fig":"pedcross","q":"横断歩道を歩行者が横断しようとしているときは、徐行して通過すればよい。","a":false,"ex":"手前で一時停止して道を譲る。","chapter":5,"section":3,"concept":"original-135"},{"id":136,"topic":"歩行者保護","fig":"hidden","q":"横断歩道の手前に止まっている車があるときは、その側方を通って前方に出る前に一時停止しなければならない。","a":true,"ex":"車の陰から人が出てくるかもしれないので一時停止。","chapter":5,"section":3,"concept":"merged-136"},{"id":137,"topic":"歩行者保護","fig":"protect","q":"白や黄色のつえを持った人が歩いているときは、警音器を鳴らして注意をうながしてから、そのそばを通るようにする。","a":false,"ex":"警音器ではなく、一時停止か徐行をする。","chapter":5,"section":3,"concept":"original-137"},{"id":138,"topic":"歩行者保護","fig":"protect","q":"児童の乗り降りのため停車している通学通園バスのそばを通るときは、必ず一時停止しなければならない。","a":false,"ex":"乗降のため停車中の通学通園バスのそばは、徐行して安全を確かめます。危険があるときは、もちろん停止が必要です。","chapter":5,"section":3,"concept":"original-138"},{"id":139,"topic":"歩行者保護","fig":"protect","q":"歩行者のそばを通るときは、安全な間隔をあければ徐行しなくてよいが、間隔があけられないときは徐行しなければならない。","a":true,"ex":"歩行者のそばを通る一般原則は、安全な間隔を空けるか徐行することです。ただし、横断歩道での横断や独り歩きの子どもなど、特別な保護の規定がある場合はそれにも従います。","chapter":5,"section":3,"concept":"original-139"},{"id":140,"topic":"歩行者保護","fig":"protect","q":"ぬかるみや水たまりのある場所では、泥や水をはねて歩行者に迷惑をかけないよう、徐行するなど注意する。","a":true,"ex":"泥はねにも注意。","chapter":5,"section":3,"concept":"original-140"},{"id":141,"topic":"徐行","fig":"slowplaces","q":"徐行とは、時速20km程度の速度で進行することをいう。","a":false,"ex":"徐行とは「直ちに停止できる速度」です。法律で一律の数字は決まっていませんが、教本の目安はおおむね時速10km以下です。","chapter":5,"section":4,"concept":"merged-141"},{"id":142,"topic":"徐行","fig":"slowplaces","q":"左右の見通しのきかない交差点では、交通整理が行われている場合や優先道路を通行している場合を除き、徐行しなければならない。","a":true,"ex":"見通しの悪い交差点は徐行場所。","chapter":5,"section":4,"concept":"original-142"},{"id":143,"topic":"徐行","fig":"slowplaces","q":"道路の曲がり角付近では、見通しがよい場合でも徐行しなければならない。","a":true,"ex":"曲がり角付近は見通しに関係なく徐行場所。","chapter":5,"section":4,"concept":"original-143"},{"id":144,"topic":"徐行","fig":"slowplaces","q":"こう配の急な上り坂は、徐行しなければならない場所である。","a":false,"ex":"徐行は「上り坂の頂上付近」と「急な下り坂」。急な上り坂は駐停車禁止。","chapter":5,"section":4,"concept":"merged-144"},{"id":145,"topic":"徐行","fig":"slowplaces","q":"こう配の急な下り坂では、徐行しなければならないうえに、追い越しも禁止されている。","a":true,"ex":"急な下り坂は徐行場所で、追い越し禁止場所でもある。","chapter":5,"section":4,"concept":"original-145"},{"id":146,"topic":"速度","fig":"speed","q":"原付は、最高速度の標識がない一般道路では、時速40kmまで出すことができる。","a":false,"ex":"原付の法定最高速度は時速30km。","chapter":5,"section":4,"concept":"merged-29"},{"id":147,"topic":"停止距離","fig":"distance","q":"速度が2倍になると、制動距離はおよそ2倍になる。","a":false,"ex":"路面などの条件が同じなら、制動距離はおおむね速度の2乗に比例するため約4倍です。空走距離を含めた停止距離とは区別します。","chapter":5,"section":4,"concept":"original-147"},{"id":148,"topic":"停止距離","fig":"stop60","q":"雨にぬれた路面では、乾いた路面より停止距離が長くなる。","a":true,"ex":"滑りやすく制動距離が伸びる。","chapter":5,"section":4,"concept":"merged-148"},{"id":149,"topic":"停止距離","fig":"distance","q":"疲れているときは、危険を感じてからブレーキが効き始めるまでの空走距離が長くなる。","a":true,"ex":"反応が遅れるので空走距離が伸びる。","chapter":5,"section":4,"concept":"original-149"},{"id":150,"topic":"交差点","fig":"turnway","q":"左折するときは、大回りにならないよう、交差点の直前で左端に寄り、交差点の中心付近を通って徐行する。","a":false,"ex":"あらかじめ左端に寄り、交差点の側端（角）に沿って徐行する。","chapter":5,"section":7,"concept":"merged-150"},{"id":151,"topic":"交差点","fig":"turnway","q":"一方通行ではない道路で普通自動車が右折するときは、あらかじめできるだけ道路の中央に寄り、交差点の中心のすぐ内側を徐行しながら通行する。","a":true,"ex":"普通自動車の基本の右折方法です。一方通行では右端に寄ります。通行すべき部分が標示されているときは、その標示に従います。","chapter":5,"section":7,"concept":"original-151"},{"id":152,"topic":"交差点","fig":"rightturn","q":"交差点で右折するとき、対向車が左折しようとしている場合は、右折車が先に進むことができる。","a":false,"ex":"対向の直進車・左折車が先。","chapter":5,"section":7,"concept":"original-152"},{"id":153,"topic":"交差点","fig":"turnway","q":"左折するときは、後ろから来る二輪車などを巻き込まないよう、左後方の安全を確かめる。","a":true,"ex":"左折は巻き込みに注意。","chapter":5,"section":7,"concept":"original-153"},{"id":154,"topic":"交差点","fig":"yield","q":"交通整理の行われていない交差点で、交差する道路が優先道路のときは、徐行して優先道路の車の進行を妨げてはいけない。","a":true,"ex":"優先道路の車が先。","chapter":5,"section":7,"concept":"original-154"},{"id":155,"topic":"交差点","fig":"yield","q":"交通整理の行われていない交差点で、交差する道路の幅が明らかに広いときは、徐行して広い道路の車の進行を妨げてはいけない。","a":true,"ex":"広い道路の車が先。","chapter":5,"section":7,"concept":"original-155"},{"id":156,"topic":"交差点","fig":"yield","q":"交通整理がなく、互いに優先道路ではない、同程度の道幅の交差点では、右方から来る車の進行を妨げてはならない。","a":false,"ex":"この条件では左方から来る車の進行を妨げてはいけません。停止の標識がある場合などは、その指示に従います。","chapter":5,"section":7,"concept":"merged-156"},{"id":157,"topic":"交差点","fig":"zones","q":"図の白い枠と白い×で示された部分では、前方の状況によりその中で停止するおそれがあるときは、その中に入ってはいけない。","a":true,"ex":"白い×の中で止まりそうなら入らない。","chapter":5,"section":7,"concept":"merged-157"},{"id":158,"topic":"交差点","fig":"roundabout","q":"環状交差点では、左回り（反時計回り）に通行する。","a":false,"ex":"環状交差点は右回り（時計回り）。","chapter":5,"section":7,"concept":"original-158"},{"id":159,"topic":"追い越し","fig":"passdef","q":"追い越しをするときは、原則として前の車の右側を通行する。","a":true,"ex":"追い越しは右側から。","chapter":5,"section":6,"concept":"merged-159"},{"id":160,"topic":"追い越し","fig":"leftpass","q":"前の車が右折するため道路の中央に寄って通行しているときは、その右側を追い越す。","a":false,"ex":"その場合は左側から追い越す。","chapter":5,"section":6,"concept":"merged-45"},{"id":161,"topic":"追い越し","fig":"passdef","q":"前の車が自動車を追い越そうとしているときに、さらにその車を追い越す二重追い越しをしてはいけない。","a":true,"ex":"二重追い越しは禁止。","chapter":5,"section":6,"concept":"original-161"},{"id":162,"topic":"追い越し","fig":"pass","q":"道路の曲がり角付近であっても、見通しがよければ追い越しをしてもよい。","a":false,"ex":"曲がり角付近は、見通しに関係なく追い越し禁止。","chapter":5,"section":6,"concept":"original-162"},{"id":163,"topic":"追い越し","fig":"pass","q":"踏切とその手前30m以内は追い越しが禁止されており、踏切を渡った先の30m以内も同じく禁止されている。","a":false,"ex":"踏切そのものと「手前」30m以内が対象です。通過後30mがこの理由で一律に禁止されるわけではありません。他の規制や安全確認は必要です。","chapter":5,"section":6,"concept":"original-163"},{"id":164,"topic":"追い越し","fig":"passdef","q":"追い越されるときは、追い越しが終わるまで速度を上げてはならず、十分な余地がない場合はできるだけ左に寄って進路を譲る。","a":true,"ex":"追い越される側は速度を上げず、必要なら左に寄る。","chapter":5,"section":6,"concept":"merged-164"},{"id":165,"topic":"追い越し","fig":"leftpass","q":"トンネルの中は、車両通行帯があってもなくても追い越しが禁止されている。","a":false,"ex":"禁止なのは車両通行帯のないトンネル。","chapter":5,"section":6,"concept":"merged-24"},{"id":166,"topic":"合図","fig":"timing","q":"進路を変えるときの合図は、進路を変えようとする地点の約30m手前で行う。","a":false,"ex":"進路変更は約3秒前。30m手前は右左折・転回。","chapter":5,"section":5,"concept":"merged-35"},{"id":167,"topic":"合図","fig":"timing","q":"右左折の合図は、右左折しようとする地点から30m手前の地点に達したときに行う。","a":true,"ex":"右左折・転回は30m手前。","chapter":5,"section":5,"concept":"merged-42"},{"id":168,"topic":"合図","fig":"timing2","q":"合図は相手に意図が伝わればよいので、右左折が終わる前にやめてもかまわない。","a":false,"ex":"合図は、その行為が終わるまで続ける。","chapter":5,"section":5,"concept":"original-168"},{"id":169,"topic":"進路変更","fig":"lanes","q":"進路を変えると後ろから来る車が急ブレーキや急ハンドルで避けなければならないような場合は、進路を変えてはいけない。","a":true,"ex":"後続車の妨げになる進路変更は禁止。","chapter":5,"section":5,"concept":"original-169"},{"id":170,"topic":"警音器","fig":"horn","q":"警音器は、「警笛鳴らせ」の標識がある場所のほか、危険を避けるためやむを得ない場合にも鳴らすことができる。","a":true,"ex":"鳴らす義務があるのは「警笛鳴らせ」の場所と、「警笛区間」内の見通しのきかない交差点・曲がり角・上り坂の頂上です。危険回避のためやむを得ない場合にも鳴らせます。","chapter":5,"section":5,"concept":"merged-170"},{"id":171,"topic":"警音器","fig":"horn","q":"前の車がなかなか発進しないときは、警音器を鳴らして発進をうながしてもよい。","a":false,"ex":"せかすために鳴らしてはいけない。","chapter":5,"section":5,"concept":"original-171"},{"id":172,"topic":"踏切","fig":"railway","q":"踏切を通過するときは、エンストを防ぐため、変速しないで低速ギアのまま通過する。","a":true,"ex":"踏切内でギアを変えない。","chapter":6,"section":1,"concept":"original-172"},{"id":173,"topic":"踏切","fig":"railway","q":"踏切を通過するときは、対向車との接触を避けるため、できるだけ左端に寄って通行する。","a":false,"ex":"左端は落輪の危険がある。対向車に注意しながら、やや中央寄りを通る。","chapter":6,"section":1,"concept":"original-173"},{"id":174,"topic":"踏切","fig":"railway","q":"警報機が鳴り始めていても、遮断機がまだ下りていなければ、急いで踏切に入ってもよい。","a":false,"ex":"警報機が鳴っている間は踏切に入ってはいけない。","chapter":6,"section":1,"concept":"original-174"},{"id":175,"topic":"踏切","fig":"railway","q":"踏切の向こう側が混雑していて、踏切内で止まってしまうおそれがあるときは、踏切に入ってはいけない。","a":true,"ex":"向こう側に余地がなければ入らない。","chapter":6,"section":1,"concept":"original-175"},{"id":176,"topic":"踏切","fig":"railsig","q":"警報機のある踏切で、警報機が鳴っていなければ一時停止しなくてよい。","a":false,"ex":"一時停止が不要なのは信号機が青のときだけ。","chapter":6,"section":1,"concept":"original-176"},{"id":177,"topic":"免許制度","fig":"karimen","q":"仮免許で練習するときは、図の標識を車の前と後ろの定められた位置に付ける。","a":true,"ex":"前後に付ける。","chapter":4,"section":2,"concept":"original-177"},{"id":178,"topic":"免許制度","fig":"karimen","q":"仮免許で運転するときは、その車を運転できる免許を3年以上受けている人などに同乗してもらい、指導を受けなければならない。","a":true,"ex":"助手席で指導できるのは、その車を運転できる第一種免許の経歴が通算3年以上の人、その車の第二種免許を持つ人などです。免許停止期間は経歴に含めず、停止中の人は指導できません。","chapter":4,"section":2,"concept":"merged-178"},{"id":179,"topic":"免許制度","fig":"karimen","q":"仮免許の有効期間は1年で、その間に本免許の試験に合格しなければならない。","a":false,"ex":"仮免許の有効期間は6か月。","chapter":4,"section":2,"concept":"original-179"},{"id":180,"topic":"駐停車","fig":"dist","q":"交差点とその端から5m以内の場所は駐車禁止だが、人の乗り降りのための停車はできる。","a":false,"ex":"交差点の5m以内は駐停車禁止。停車もダメ。","chapter":null,"section":8,"concept":"original-180"},{"id":181,"topic":"駐停車","fig":"fb30","q":"横断歩道や自転車横断帯と、その端から前後5m以内の場所は、駐車も停車も禁止されている。","a":true,"ex":"横断歩道の前後5mは駐停車禁止。","chapter":null,"section":8,"concept":"original-181"},{"id":182,"topic":"駐停車","fig":"hill","q":"こう配の急な下り坂は駐停車禁止だが、こう配の急な上り坂では駐停車をしてもよい。","a":false,"ex":"急な坂は上りも下りも駐停車禁止。","chapter":null,"section":8,"concept":"original-182"},{"id":183,"topic":"発進","fig":"wakaba","q":"車から降りるときは、ドアを少し開けて一度止め、後方の安全を確かめてから降りる。","a":true,"ex":"後ろから来る車や二輪車に注意。","chapter":5,"section":1,"concept":"original-183"},{"id":184,"topic":"合図","fig":"handsig","q":"図のように右腕を車の外に出し、ひじを垂直に上に曲げる合図は、左折や左への進路変更を表す。","a":true,"ex":"ひじを上に曲げる＝左。","chapter":5,"section":5,"concept":"original-184"},{"id":185,"topic":"合図","fig":"handsig","q":"図のように右腕を車の外に出して水平に伸ばす合図は、右折・転回・右への進路変更を表す。","a":true,"ex":"まっすぐ水平＝右。","chapter":5,"section":5,"concept":"merged-185"},{"id":186,"topic":"合図","fig":"handsig","q":"図のように腕を車の外に出して斜め下に伸ばし、そのまま静止させる合図は、後退することを表す。","a":false,"ex":"斜め下は徐行・停止。後退はさらに手のひらを後ろに向けて前後に動かす。","chapter":5,"section":5,"concept":"original-186"},{"id":187,"topic":"合図","fig":"handsig","q":"二輪車で左折するときは、図のように左腕を水平に伸ばして合図をしてもよい。","a":true,"ex":"左腕を水平でも、右ひじを上に曲げてもよい。","chapter":5,"section":5,"concept":"original-187"},{"id":188,"topic":"手信号","fig":"police","q":"図のように警察官が灯火を横に振っているとき、振られている方向に進む「あなたの車」に対しては、青色の信号と同じ意味である。","a":true,"ex":"灯火を振る方向に進む交通が青、それと交差する交通は赤です。法令は「振る方向」で決めています（教則の「身体の正面に平行する交通」と、ふつうは同じ方向です）。","chapter":1,"section":3,"concept":"merged-80"},{"id":189,"topic":"手信号","fig":"police","q":"図の警察官は、灯火を左右に振った後、頭上に上げた。直前の振り方向に進む「あなたの車」に対しては、黄色の信号と同じ意味になる。","a":true,"ex":"灯火を頭上に上げると、直前に振っていた方向が黄、交差する方向が赤です。教則では「身体の正面に平行する交通は黄、対面する交通は赤」と書かれ、ふつうは同じ方向を指します。","revised":true,"chapter":1,"section":3,"concept":"original-189"},{"id":201,"chapter":1,"section":2,"topic":"信号","concept":"yellow-blink","a":true,"q":"黄色の点滅信号では、他の交通に注意して進むことができる。","ex":"赤の点滅は一時停止、黄の点滅は他の交通に注意して進行です。別の停止義務がある場合は、それにも従います。","fig":"signals"},{"id":202,"chapter":1,"section":2,"topic":"補助標識","concept":"aux-time","a":false,"q":"図の規制は、午前9時には適用されない。","ex":"下の「8–20」は午前8時から午後8時までの規制を示します。午前9時は規制時間内です。","fig":"aux-rules","visual":"aux-time"},{"id":203,"chapter":1,"section":2,"topic":"補助標識","concept":"aux-except","a":false,"q":"図の「自転車を除く」という表示がある場合、一般原動機付自転車も規制の対象から外れる。","ex":"「自転車を除く」のように普通自転車を規制対象外とする補助標識は、特定小型原付も対象外にしますが、一般原付は除外されません。","fig":"aux-rules","visual":"aux-except"},{"id":204,"chapter":1,"section":2,"topic":"補助標識","concept":"aux-distance","a":true,"q":"警戒標識の下に「この先100m」という補助標識がある場合、その危険な場所が100m先にあることを示している。","ex":"「この先100m」は、本標識が示す場所までの距離を補足します。警戒標識なら、その危険な場所が100m先にあるという意味です。","fig":"aux-rules"},{"id":205,"chapter":1,"section":2,"topic":"標識","concept":"direction-only","a":false,"q":"図の標識がある交差点では、普通自動車は右折することができる。","ex":"指定方向外進行禁止の標識です。図では直進と左折だけが指定され、右折はできません。","fig":"signs","visual":"direction"},{"id":206,"chapter":1,"section":1,"topic":"道路の心得","concept":"green-permission","a":false,"q":"青信号は、周囲の状況にかかわらず必ず進まなければならないという意味である。","ex":"青は進むことができるという意味です。交差点内で止まりそうなときや危険があるときに、無理に進んではいけません。","fig":"signals"},{"id":207,"chapter":1,"section":4,"topic":"道路の心得","concept":"road-debris","a":false,"q":"車の通行が少なければ、道路に空き缶を投げ捨ててもよい。","ex":"交通量の多少にかかわらず、交通の妨げや危険になる物を道路に投げ捨ててはいけません。","fig":""},{"id":208,"chapter":1,"section":2,"topic":"標識","concept":"priority-mark","a":true,"q":"交差点の中まで中央線や車両通行帯が続いている道路は、優先道路に当たる。","ex":"優先道路は標識だけで決まりません。交差点内まで中央線や車両通行帯が続いている道路も該当します。","fig":"priority"},{"id":209,"chapter":4,"section":1,"topic":"運転者の心得","concept":"fatigue-start","a":false,"q":"強い眠気があっても、短い距離なら窓を開けて運転を始めてよい。","ex":"眠気や疲労で安全な運転ができないおそれがあるときは運転を控えます。距離が短くても同じです。","fig":"drink"},{"id":210,"chapter":4,"section":1,"topic":"免許制度","concept":"license-carry","a":true,"q":"有効な運転免許を受けていても、運転するときは免許証または免許情報が記録されたマイナンバーカードを携帯する必要がある。","ex":"免許証かマイナ免許証を携帯します。免許証の写真をスマートフォンに保存しただけでは代わりになりません。","fig":"licenses"},{"id":211,"chapter":4,"section":2,"topic":"免許制度","concept":"at-license","a":false,"q":"AT限定の普通免許を受けていれば、練習のためにMTの普通自動車を一人で運転してよい。","ex":"AT限定は免許の条件です。限定解除などの適法な手続なしに、MT車を一人で運転することはできません。","fig":"licenses"},{"id":212,"chapter":4,"section":2,"topic":"車種","concept":"new-moped","a":false,"q":"総排気量125cc以下の二輪車は、最高出力に関係なくすべて原付免許で運転できる。","ex":"新基準原付は125cc以下に加え、最高出力4.0kW以下に制御された車両です。通常の125cc二輪車を一律に原付免許で運転できるわけではありません。","fig":"licenses"},{"id":213,"chapter":5,"section":9,"topic":"AT車","concept":"at-creep","a":true,"q":"AT車では、DやRに入れると、アクセルを踏まなくても車が動き出すことがある。","ex":"クリープ現象です。停止中はブレーキをしっかり踏み、シフト位置と周囲を確認します。","fig":"at-basics"},{"id":214,"chapter":5,"section":9,"topic":"AT車","concept":"at-start","a":true,"q":"AT車のエンジンを始動するときは、駐車ブレーキとPの位置を確認し、ブレーキペダルを踏んで始動する。","ex":"先にブレーキとアクセルの位置を確かめ、ブレーキを踏んで始動します。車種の取扱説明書にも従います。","fig":"at-basics"},{"id":215,"chapter":5,"section":9,"topic":"AT車","concept":"merged-215","a":false,"q":"AT車でPからDへ切り替えるときは、ブレーキペダルから足を離してから操作する。","ex":"ブレーキを踏んだまま操作し、Dであることを確認します。足を離して操作すると急に動き出すおそれがあります。","fig":"at-basics"},{"id":216,"chapter":5,"section":9,"topic":"AT車","concept":"merged-216","a":true,"q":"AT車は、エンジン始動直後やエアコン作動時に回転数が高くなり、急に動き出すことがある。","ex":"このようなときは、ブレーキペダルを特にしっかり踏んで、急な発進を防ぎます。","fig":"at-basics"},{"id":217,"chapter":5,"section":9,"topic":"AT車","concept":"at-p-moving","a":false,"q":"AT車では、停止する直前にPに入れると、より確実に車を止められる。","ex":"Pへの操作は車が完全に停止してから行います。走行中のP操作で車を止めようとしてはいけません。","fig":"at-basics"},{"id":218,"chapter":5,"section":9,"topic":"運転支援","concept":"asv-limit","a":false,"q":"衝突被害軽減ブレーキが付いた車は必ず自動で止まるので、前方確認を減らしてもよい。","ex":"運転支援装置には作動条件と限界があります。装置を過信せず、運転者自身が周囲を確認して操作します。","fig":"at-basics"},{"id":219,"chapter":5,"section":1,"topic":"発進","concept":"start-around","a":true,"q":"車に乗る前は、車の前後や下に子どもなどがいないか、安全を確かめる。","ex":"乗車後には見えにくい場所があります。乗る前の確認と、発進直前の確認を組み合わせます。","fig":"start-check"},{"id":220,"chapter":5,"section":1,"topic":"発進","concept":"mirror-blind","a":false,"q":"発進前にバックミラーを見て異常がなければ、死角を直接見る必要はない。","ex":"ミラーには死角があります。周囲を直接見て確かめ、合図後にも改めて安全確認をして発進します。","fig":"start-check"},{"id":221,"chapter":5,"section":1,"topic":"発進","concept":"merged-221","a":true,"q":"路端から発進するときは、周囲を確かめて合図を出し、もう一度安全を確かめてから発進する。","ex":"合図を出すだけでは安全は確保できません。合図の後にも後方などを確認します。","fig":"start-check"},{"id":222,"chapter":5,"section":2,"topic":"通行の基本","concept":"bus-depart","a":true,"q":"停留所の路線バスが発進の合図をしたときは、急ブレーキなどで避けなければならない場合を除き、発進を妨げてはならない。","ex":"後方の車は路線バスの発進を妨げません。ただし急ブレーキ・急ハンドルを必要とする場合には例外があります。","fig":"bus-depart"},{"id":223,"chapter":5,"section":2,"topic":"通行の基本","concept":"bus-depart-exception","a":false,"q":"停留所の路線バスが発進の合図をしたときは、急ブレーキが必要でも必ずその場で停止しなければならない。","ex":"急ブレーキや急ハンドルで避けなければならない場合は例外です。後続車にも注意して安全に対応します。","fig":"bus-depart"},{"id":224,"chapter":5,"section":5,"topic":"進路変更","concept":"merged-224","a":false,"q":"同じ方向に進む車線の境界が黄色の実線でも、安全確認をすれば、その線を越えて進路変更してよい。","ex":"黄色の線で区画された車両通行帯では、その線を越える進路変更が禁止されています。中央線の黄色とは区別します。","fig":"lanes"},{"id":225,"chapter":5,"section":6,"topic":"行き違い","concept":"obstacle-yield","a":true,"q":"自分の進路前方に障害物があるときは、あらかじめ停止か減速をして、対向車に道を譲る。","ex":"障害物を避ける側が、対向車の進路を妨げないようにします。早めに間隔と速度を調整します。","fig":"meeting"},{"id":226,"chapter":5,"section":6,"topic":"行き違い","concept":"meeting-gap","a":false,"q":"狭い道路ですれ違うときは、相手が止まると考えて速度を変えずに進むのがよい。","ex":"相手任せにせず、安全な間隔を確保します。余裕がなければ減速や停止をして、無理なすれ違いを避けます。","fig":"meeting"},{"id":227,"chapter":5,"section":2,"topic":"通行の基本","concept":"merged-227","a":false,"q":"道路の左側部分の幅が6m以上でも、中央線が白の破線なら、追い越しのため右側部分にはみ出してよい。","ex":"白の破線でも、追い越しのために右側へはみ出せるのは、左側部分の幅が6m未満で、右側部分を見通せ、対向車の妨げにならない場合に限られます。","fig":"centerline"},{"id":228,"chapter":5,"section":6,"topic":"追い越し","concept":"pass-speed","a":false,"q":"追い越しを早く終えるためなら、指定最高速度を一時的に超えてもよい。","ex":"追い越し中も最高速度を守ります。速度制限内で安全に追い越せないときは、追い越しを控えます。","fig":"passdef"},{"id":229,"chapter":5,"section":4,"topic":"速度","concept":"residential-30","a":true,"q":"中央線・車両通行帯がなく、往復方向が構造的に分離されていない一般道路で、最高速度の指定もない場合、普通自動車の法定最高速度は30km/hである（自動車専用道路を除く）。","ex":"2026年9月1日からの区分です。中央線などがない一般道路は原則30km/h。標識等の指定があれば指定速度に従います。","fig":"speed-2026"},{"id":230,"chapter":5,"section":4,"topic":"速度","concept":"center-60","a":true,"q":"中央線のある一般道路で最高速度の指定がない場合、普通自動車の法定最高速度は60km/hである。","ex":"中央線や車両通行帯のある一般道路などでは、引き続き60km/hです。状況に応じた安全な速度で走ります。","fig":"speed-2026"},{"id":231,"chapter":5,"section":4,"topic":"速度","concept":"specified-over-default","a":false,"q":"中央線のない生活道路に最高速度40km/hの標識があっても、普通自動車は法定速度30km/hを必ず上限にしなければならない。","ex":"最高速度の指定がある場合は、その指定が優先します。この場合の最高速度は40km/hですが、危険ならさらに速度を落とします。","fig":"speed-2026"},{"id":232,"chapter":5,"section":4,"topic":"速度","concept":"edge-not-center","a":false,"q":"中央線も車両通行帯もない一般道路でも、道路の両端に白線があれば、必ず法定最高速度は60km/hになる。","ex":"道路の端を示す車道外側線は中央線ではありません。構造的な上下線分離等もない一般道路では、原則30km/hの区分です。","fig":"speed-2026"},{"id":233,"chapter":5,"section":4,"topic":"速度","concept":"divided-60","a":true,"q":"往復の方向別に中央分離帯で分かれた一般道路で最高速度の指定がなければ、普通自動車の法定最高速度は60km/hである。","ex":"往復の方向が構造的に分離されている一般道路は60km/hの区分です。最高速度の指定があれば、その指定が優先します。","fig":"speed-2026"},{"id":234,"chapter":5,"section":7,"topic":"環状交差点","concept":"round-entry","a":true,"q":"環状交差点に入るときは徐行し、すでに環状交差点内を通行している車の進行を妨げてはならない。","ex":"進入時は徐行し、環状交差点内の車を優先します。出口付近の歩行者にも注意します。","fig":"roundabout"},{"id":235,"chapter":5,"section":7,"topic":"環状交差点","concept":"round-signal","a":false,"q":"環状交差点へ入るときは必ず左の合図を出し、そのまま出るときまで出し続ける。","ex":"入るときの合図は不要です。出るときは、出ようとする地点の直前の出口を通過したときから左の合図を出します。","fig":"roundabout"},{"id":236,"chapter":5,"section":7,"topic":"環状交差点","concept":"round-first-exit","a":true,"q":"環状交差点に入って最初の出口で出る場合は、入ったときから左の合図を出す。","ex":"最初の出口では、進入したときから左の合図を出し、出終わるまで続けます。","fig":"roundabout"},{"id":237,"chapter":5,"section":7,"topic":"交差点","concept":"wide-not-left","a":false,"q":"交通整理のない交差点で自分の道路が明らかに狭い場合でも、相手の右側にいるなら自分が優先する。","ex":"明らかに広い交差道路の車を優先し、自分は徐行します。左方優先を道幅や優先道路の条件より先に当てはめてはいけません。","fig":"yield"},{"id":238,"chapter":5,"section":7,"topic":"交差点","concept":"priority-ped","a":false,"q":"優先道路を走っていれば、横断歩道を渡ろうとする歩行者がいても、車が先に通過してよい。","ex":"優先道路でも歩行者保護の義務は変わりません。横断歩道の手前で一時停止して歩行者に道を譲ります。","fig":"pedcross"},{"id":239,"chapter":5,"section":3,"topic":"歩行者保護","concept":"merged-239","a":true,"q":"交差点やその近くに横断歩道がなくても、歩行者が横断しているときは、その通行を妨げてはならない。","ex":"横断歩道がないことを理由に、横断中の歩行者の通行を妨げてはいけません。","fig":"protect"},{"id":240,"chapter":5,"section":3,"topic":"歩行者保護","concept":"bike-crossing","a":true,"q":"自転車横断帯を横断しようとする自転車がいるときは、その手前で一時停止し、自転車に道を譲る。","ex":"横断歩道の歩行者と同様に、自転車横断帯を横断する自転車の通行を優先します。","fig":"pedcross"},{"id":241,"chapter":5,"section":5,"topic":"警音器","concept":"horn-zone","a":false,"q":"「警笛区間」の標識がある区間では、見通しがよい直線道路でも、常に警音器を鳴らし続ける。","ex":"区間内の見通しのきかない交差点・曲がり角・上り坂の頂上で鳴らします。常に鳴らし続ける意味ではありません。","fig":"horn"},{"id":242,"chapter":6,"section":2,"topic":"坂道・カーブ","concept":"hill-yield","a":true,"q":"坂道で行き違うときは、近くに待避所がある場合などを除き、下りの車が上りの車に道を譲る。","ex":"上り坂での発進が難しいためです。近くに待避所がある車は、そこに入って相手に譲ります。","fig":"meeting"},{"id":243,"chapter":6,"section":2,"topic":"坂道・カーブ","concept":"hill-refuge","a":false,"q":"坂道では上りの車のすぐ近くに待避所があっても、下りの車が必ず長い距離を後退して譲らなければならない。","ex":"上り・下りにかかわらず、近くに待避所がある場合は、そこへ入って相手に道を譲ります。","fig":"meeting"},{"id":244,"chapter":6,"section":2,"topic":"坂道・カーブ","concept":"cliff-yield","a":true,"q":"片側が転落のおそれのある崖の道路で安全に行き違えないときは、崖側の車があらかじめ停止して道を譲る。","ex":"崖側の車が動くと転落の危険があります。あらかじめ止まって安全を確保します。","fig":"meeting"},{"id":245,"chapter":5,"section":4,"topic":"停止距離","concept":"stopping-definition","a":false,"q":"停止距離とは、ブレーキが効き始めてから車が止まるまでの距離だけをいう。","ex":"停止距離は空走距離と制動距離の合計です。ブレーキが効き始めてからの距離だけなら制動距離です。","fig":"distance"},{"id":246,"chapter":5,"section":4,"topic":"停止距離","concept":"reaction-speed","a":true,"q":"反応時間が同じなら、速度が2倍になると空走距離は約2倍になる。","ex":"空走距離は反応時間中に進む距離です。制動距離がおおむね速度の2乗に比例することと区別します。","fig":"distance"},{"id":247,"chapter":5,"section":5,"topic":"合図","concept":"signal-no-action","a":false,"q":"周囲に自分の車の存在を知らせるため、進路を変えないときも方向指示器を出して走るとよい。","ex":"行為をしないのに合図を出すと、ほかの交通に誤解を与えます。必要な行為に合わせて合図します。","fig":"timing2"},{"id":248,"chapter":5,"section":2,"topic":"通行の基本","concept":"designated-lane","a":true,"q":"交差点の手前で進行方向別に通行区分が指定されているときは、指定された通行帯を通る。","ex":"左折・直進・右折に応じた通行帯を早めに確認します。進路変更禁止の標示がある場合は、それにも従います。","fig":"lanes"},{"id":249,"chapter":5,"section":6,"topic":"追い越し","concept":"pass-sequence","a":true,"q":"追い越しのため進路を変えるときも、合図を出してから約3秒後に、安全を確かめて進路を変える。","ex":"追い越しでも進路変更の合図が必要です。合図、安全確認、速度制限を守って行います。","fig":"timing"},{"id":250,"chapter":5,"section":6,"topic":"追い越し","concept":"merged-250","a":false,"q":"追い越した車のすぐ前へ戻れば、対向車線にいる時間を短くできるので安全である。","ex":"追い越した車がルームミラーで見える程度の距離を取り、合図と安全確認をして緩やかに戻ります。","fig":"passdef"},{"id":251,"chapter":5,"section":2,"topic":"通行の基本","concept":"roadside-driving","a":false,"q":"渋滞しているときは、歩行者がいない路側帯を普通自動車で走り続けてもよい。","ex":"路側帯は歩行者の通行などのための部分です。渋滞を避ける目的で普通自動車が走行してよい場所ではありません。","fig":"keepleft"},{"id":252,"chapter":5,"section":1,"topic":"発進","concept":"mirror-adjust","a":true,"q":"座席を正しい位置に合わせてから、後方を見やすいようにミラーを調整する。","ex":"運転姿勢を整えてからミラーを合わせます。走行中の調整は避け、発進前に済ませます。","fig":"posture"},{"id":253,"chapter":4,"section":1,"topic":"運転者の心得","concept":"drunk-passenger","a":false,"q":"飲酒した運転者だと知っていても、自分が運転を代わらなければ、その車で送ってほしいと頼んで同乗してよい。","ex":"飲酒運転をする人に、送るよう要求・依頼して同乗することも禁止されています。","fig":"drink"},{"id":254,"chapter":4,"section":2,"topic":"免許制度","concept":"learner-purpose","a":false,"q":"仮免許と適格な指導者があれば、運転練習以外の目的だけで自由に自動車を運転してよい。","ex":"仮免許は練習等のための免許です。指導者の同乗、標識の掲示、練習目的などの条件を守ります。","fig":"karimen"},{"id":255,"chapter":5,"section":7,"topic":"交差点","concept":"right-designated","a":true,"q":"交差点で右折する経路が道路標示で指定されているときは、その標示に従って通行する。","ex":"原則の曲がり方だけでなく、標示による指定にも従います。歩行者や対向車の安全も確かめます。","fig":"turnway"},{"id":256,"chapter":5,"section":3,"topic":"歩行者保護","concept":"tram-no-gap","a":false,"q":"安全地帯のない停留所で路面電車が乗降のため停車中でも、乗り降りする人が見当たらなければ、間隔が1mでもその左側を徐行して通過できる。","ex":"安全地帯がない場合、通過できる例外には、乗り降りする人がいないことに加えて1.5m以上の間隔が必要です。","fig":"tram3"},{"id":257,"chapter":1,"section":2,"topic":"標識","concept":"stop-double-check","a":true,"q":"図の標識がある交差点では、停止線で一時停止し、そこから見通せない場合は安全を確かめながら慎重に進む。","ex":"見通しのよい位置まで進んでから初めて止まるのではありません。まず停止線の直前で一時停止します。","fig":"stopline","visual":"119"},{"id":258,"chapter":5,"section":4,"topic":"速度","concept":"limit-not-target","a":false,"q":"最高速度の標識は、その速度まで加速して走らなければならないという意味である。","ex":"最高速度は上限です。道幅・歩行者・天候などに応じて、それより遅い安全な速度で走ります。","fig":"speed"},{"id":259,"chapter":5,"section":5,"topic":"進路変更","concept":"blind-signal","a":false,"q":"進路変更の合図を出して3秒たてば、後続車に急ブレーキをかけさせる場合でも進路を変えてよい。","ex":"3秒前の合図だけで優先権は得られません。後続車に急な回避をさせる進路変更は禁止です。","fig":"lanes"},{"id":260,"chapter":6,"section":1,"topic":"踏切","concept":"rail-window","a":true,"q":"信号機に従って通過する場合を除き、踏切の直前で一時停止し、窓を開けるなどして目と耳で安全を確かめる。","ex":"警報機の音だけに頼らず、左右の列車と踏切の先の状況も確認してから通過します。","fig":"railway"},{"id":261,"chapter":5,"section":2,"topic":"通行の基本","concept":"cycle-lateral-gap","a":true,"q":"進路を変えずに自転車の右側を通過する場合、十分な間隔がなければ、その間隔に応じた安全な速度で進行しなければならない。","ex":"2026年4月1日施行の規定です。できる限り間隔を取り、間隔が十分でないときは安全な速度にします。追い越し時の安全義務にも注意します。","fig":"cycle-gap"},{"id":262,"chapter":4,"section":1,"topic":"免許制度","concept":"glasses-condition","a":false,"q":"免許の条件が「眼鏡等」でも、近所だけなら条件を満たさずに運転してよい。","ex":"運転距離にかかわらず、免許に付された条件を守ります。運転前に免許証と条件を確認します。","fig":"licenses"},{"id":263,"chapter":4,"section":1,"topic":"運転者の心得","concept":"drive-plan","a":true,"q":"長時間の運転では、運転経路や休憩場所を計画し、おおむね2時間に1回は休息をとるようにする。","ex":"眠気を感じた場合は2時間になるまで待たず、速やかに休息をとります。自分の体調と技能に合った計画が必要です。","fig":"drink"},{"id":264,"chapter":4,"section":2,"topic":"免許制度","concept":"towing-license","a":false,"q":"総重量750kg以下の車を普通自動車でけん引する場合でも、必ずけん引免許が必要である。","ex":"車の総重量が750kg以下の場合や故障車をけん引する場合には、けん引免許を必要としない例外があります。けん引する自動車に応じた免許は必要です。","fig":"licenses"},{"id":265,"chapter":4,"section":2,"topic":"免許制度","concept":"emergency-driver","a":false,"q":"緊急自動車を緊急用務で運転する資格は、その車種を運転できる免許があれば、それだけで十分である。","ex":"車種に応じた免許に加え、一定の年齢や運転経験年数（例：普通自動車の緊急自動車は普通免許などの期間が2年以上）の要件を満たす必要があります。","fig":"licenses"}];
const ASSESSMENT_Q=[{"id":1001,"chapter":1,"section":2,"topic":"信号","concept":"A-green","a":true,"q":"信号が青でも、進んだ先が詰まっていれば、無理に発進しなくてよい。","ex":"青信号は進行の許可です。進む義務ではなく、前方の状況を確認して判断します。","fig":"signals","set":13,"form":"A"},{"id":1002,"chapter":1,"section":2,"topic":"信号","concept":"A-yellow","a":true,"q":"交差点の停止位置のすぐ手前で黄信号になり、安全に止まれない場合は、停止位置を越えて進める。","ex":"黄は原則停止ですが、停止位置に近づいていて安全に止まれない場合は例外です。","fig":"signals","set":13,"form":"A"},{"id":1003,"chapter":1,"section":2,"topic":"信号","concept":"A-red-blink","a":false,"q":"深夜、赤の点滅信号の交差点で左右に車が見えなかったので、徐行だけで通過した。","ex":"赤の点滅では、車が見えなくても停止位置で一時停止し、安全を確認します。","fig":"signals","set":13,"form":"A"},{"id":1004,"chapter":1,"section":2,"topic":"信号","concept":"A-arrow","a":false,"q":"二段階右折が必要な一般原付で、赤信号と右向きの青矢印が出たので、自動車と同じように右折した。","ex":"右向きの青矢印でも、二段階右折する一般原付は直接右折できません。","fig":"arrowsig","set":13,"form":"A"},{"id":1005,"chapter":1,"section":3,"topic":"手信号","concept":"A-police-side","a":true,"q":"図の位置から近づく車に対し、この手信号は黄信号と同じ意味になる。","ex":"腕を垂直に上げた手信号は、身体の正面に平行する交通に対して黄です。図の車はその方向に進んでいます。","fig":"police","set":13,"visual":"78","form":"A"},{"id":1006,"chapter":1,"section":3,"topic":"手信号","concept":"A-police-priority","a":true,"q":"図の車は、信号機が青でも、警察官の手信号に従って停止しなければならない。","ex":"信号機と警察官の手信号が異なるときは警察官に従います。身体の正面に向かう図の車に対しては赤と同じです。","fig":"policeorder","set":13,"visual":"115","form":"A"},{"id":1007,"chapter":1,"section":2,"topic":"標識","concept":"A-entry","a":false,"q":"図の標識がある入口から、自転車に乗ったまま進入してもよい。","ex":"自転車も車両です。「自転車を除く」などの条件がない限り、この方向から進入できません。","fig":"noentry","set":13,"visual":"13","form":"A"},{"id":1008,"chapter":1,"section":2,"topic":"標識","concept":"A-minimum","a":true,"q":"図の数字は、その道路で指定された最低速度を表している。","ex":"数字の下に青い横線があるのは最低速度の標識です。最高速度と取り違えないようにします。","fig":"signs","set":13,"visual":"28","form":"A"},{"id":1009,"chapter":1,"section":2,"topic":"補助標識","concept":"A-time","a":false,"q":"図の標識による規制は、午後9時にも適用される。","ex":"「8–20」は午前8時から午後8時までです。午後9時は、この標識に示された時間の範囲外です。他の規制は別に確認します。","fig":"aux-rules","set":13,"visual":"aux-time","form":"A"},{"id":1010,"chapter":1,"section":2,"topic":"標識","concept":"A-directions","a":true,"q":"図の標識のある交差点では、普通自動車は直進または左折の方向に進める。","ex":"図で指定されている方向は直進と左折です。信号や歩行者の状況にも従って進みます。","fig":"aux-rules","set":13,"visual":"direction","form":"A"},{"id":1011,"chapter":1,"section":2,"topic":"標識・標示","concept":"A-noarea","a":false,"q":"図の部分は、渋滞を避けるために止まらず通り抜けるだけなら入ってよい。","ex":"黄色い枠に白い斜線は立入り禁止部分です。停止しなければ進入できる場所ではありません。","fig":"zones","set":13,"visual":"90","form":"A"},{"id":1012,"chapter":1,"section":1,"topic":"道路の心得","concept":"A-care","a":true,"q":"自分が優先する場面でも、他の車や歩行者の動きを予測し、危険を避けるよう運転する。","ex":"優先関係があっても、危険を避ける配慮や安全確認を省いてよいわけではありません。","fig":"","set":13,"form":"A"},{"id":1013,"chapter":4,"section":1,"topic":"免許制度","concept":"A-carry","a":false,"q":"免許証を自宅に忘れたが、有効な免許証の写真がスマートフォンにあるので、そのまま運転してよい。","ex":"免許証の写真は携帯義務を満たしません。免許証またはマイナ免許証の携帯が必要です。","fig":"licenses","set":13,"form":"A"},{"id":1014,"chapter":4,"section":1,"topic":"運転者の心得","concept":"A-drug","a":true,"q":"花粉症の薬を飲んで眠気が出ているときは、予定があっても運転を控える。","ex":"薬による眠気で安全な運転ができないおそれがあるときは、運転を避けます。","fig":"drink","set":13,"form":"A"},{"id":1015,"chapter":4,"section":2,"topic":"免許制度","concept":"A-supervisor","a":true,"q":"仮免許の練習を指導する人の第一種免許の経歴を数えるとき、免許停止中だった期間は含めない。","ex":"指導資格の経歴は、停止期間を除いて通算します。現在停止中の人も指導者にはなれません。","fig":"karimen","set":13,"form":"A"},{"id":1016,"chapter":4,"section":2,"topic":"免許制度","concept":"A-motorcycle","a":false,"q":"普通免許しか持っていなくても、排気量250ccの二輪車を運転してよい。","ex":"250ccの二輪車には対応する二輪免許が必要です。普通免許で運転できる一般原付とは別です。","fig":"licenses","set":13,"form":"A"},{"id":1017,"chapter":5,"section":1,"topic":"発進","concept":"A-blindspot","a":false,"q":"乗車前に周囲を一度見たので、その後はミラーを見ずにすぐ発進してよい。","ex":"乗車している間に周囲の状況は変わります。発進の直前にも前後左右を確かめ、合図後に再確認します。","fig":"start-check","set":13,"form":"A"},{"id":1018,"chapter":5,"section":1,"topic":"運転者の心得","concept":"A-belt","a":true,"q":"一般道路の短距離移動でも、法令の例外に当たらなければ、後部座席の同乗者にも座席ベルトを着用させる。","ex":"道路の種類や移動距離を理由に後席のベルトが不要になることはありません。","fig":"seatbelt","set":13,"form":"A"},{"id":1019,"chapter":5,"section":1,"topic":"発進","concept":"A-door","a":false,"q":"降車するとき、ミラーに後続車が映っていなければ、ドアを一気に大きく開けてもよい。","ex":"ミラーには死角があります。後方を確認し、ドアを少し開けてさらに確かめてから降ります。","fig":"door","set":13,"form":"A"},{"id":1020,"chapter":5,"section":1,"topic":"発進","concept":"A-posture","a":true,"q":"ブレーキを十分に踏んでも膝が少し曲がるように、発進前に座席位置を調整する。","ex":"足が伸びきらない位置に合わせると、必要な踏力をかけやすくなります。","fig":"posture","set":13,"form":"A"},{"id":1021,"chapter":5,"section":2,"topic":"通行の基本","concept":"A-center","a":false,"q":"左側部分の幅が7mある道路で、白い破線の中央線を越えて追い越した。対向車がいなければ、この方法でよい。","ex":"白い破線でも、追い越しのため右側にはみ出せる幅の条件は原則6m未満です。","fig":"centerline","set":13,"form":"A"},{"id":1022,"chapter":5,"section":2,"topic":"通行の基本","concept":"A-roadside","a":false,"q":"渋滞の列を抜けるため、歩行者のいない路側帯を普通自動車で走行した。","ex":"歩行者がいなくても、路側帯を渋滞回避の走行経路にしてはいけません。","fig":"keepleft","set":13,"form":"A"},{"id":1023,"chapter":5,"section":2,"topic":"緊急自動車","concept":"A-emergency","a":true,"q":"一方通行で緊急自動車が近づき、左へ寄ると通り道を塞いでしまうので、右側へ寄って道を譲った。","ex":"一方通行では、左に寄るとかえって妨げになる場合、右に寄って譲れます。交差点付近なら交差点を避けた停止も必要です。","fig":"emergency","set":13,"form":"A"},{"id":1024,"chapter":5,"section":2,"topic":"通行の基本","concept":"A-buslane","a":true,"q":"普通自動車で路線バス等優先通行帯に入る前に、混雑で他の通行帯へ出られなくなるおそれがあると分かったので、入るのをやめた。","ex":"バスが来たときに出られないおそれがある場合、原則として優先通行帯に入ってはいけません。","fig":"buslane","set":13,"form":"A"},{"id":1025,"chapter":5,"section":2,"topic":"通行の基本","concept":"A-busstart","a":false,"q":"停留所の路線バスが発進の合図をしたが、後方の車が譲る必要はなく、加速して先に通り過ぎてよい。","ex":"急ブレーキ等が必要な場合を除き、後方の車はバスの発進を妨げてはいけません。","fig":"bus-depart","set":13,"form":"A"},{"id":1026,"chapter":5,"section":3,"topic":"歩行者保護","concept":"A-crosswalk","a":true,"q":"駐車車両で横断歩道の端が見えず、横断する人がいるか分からないので、手前で止まれる速度に落とした。","ex":"人がいないことが明らかでない場合、横断歩道の手前で停止できる速度で近づきます。","fig":"pedcross","set":13,"form":"A"},{"id":1027,"chapter":5,"section":3,"topic":"歩行者保護","concept":"A-hidden","a":false,"q":"横断歩道の直前に止まっている車を追い抜くとき、人が見えないので、停止せずにその前へ出てよい。","ex":"その停止車両の側方を通って前に出る前に、一時停止して安全を確かめます。","fig":"hidden","set":13,"form":"A"},{"id":1028,"chapter":5,"section":3,"topic":"歩行者保護","concept":"A-child","a":true,"q":"一人歩きの小さな子どもがいるので、十分に離れられそうでも徐行または一時停止して安全を確保する。","ex":"一人歩きの子どもには、特別な保護として徐行または一時停止が必要です。","fig":"protect","set":13,"form":"A"},{"id":1029,"chapter":5,"section":3,"topic":"路面電車","concept":"A-tram","a":false,"q":"安全地帯のない停留所で停車している路面電車の乗降が終わったので、間隔が1mでも徐行して左側を通過できる。","ex":"乗降する人がいないことに加え、路面電車との間に1.5m以上の間隔が必要です。","fig":"tram3","set":13,"form":"A"},{"id":1030,"chapter":5,"section":3,"topic":"歩行者保護","concept":"A-unmarked-cross","a":true,"q":"横断歩道のない交差点を歩行者が横断中なので、その歩行者の通行を妨げないようにした。","ex":"交差点やその近くでは、横断歩道がなくても横断中の歩行者の通行を妨げてはいけません。","fig":"protect","set":13,"form":"A"},{"id":1031,"chapter":5,"section":4,"topic":"速度","concept":"A-speed30","a":false,"q":"中央線も車両通行帯も上下線の構造的な分離もない一般道路では、最高速度の指定がなければ普通自動車は50km/hで走ってよい（自動車専用道路を除く）。","ex":"この道路の法定最高速度は30km/hです。2026年9月1日からの区分を適用します。","fig":"speed-2026","set":13,"form":"A"},{"id":1032,"chapter":5,"section":4,"topic":"速度","concept":"A-speed40","a":true,"q":"中央線のない生活道路でも、最高速度40km/hの指定があれば、普通自動車の最高速度は40km/hである。","ex":"標識等による指定が優先します。ただし、指定速度以内でも危険なら速度を落とします。","fig":"speed-2026","set":13,"form":"A"},{"id":1033,"chapter":5,"section":4,"topic":"停止距離","concept":"A-distance","a":false,"q":"危険に気付いてからブレーキを踏むまでに進んだ距離は、停止距離に含めなくてよい。","ex":"停止距離は、空走距離と制動距離の合計です。反応している間に進む距離も含めます。","fig":"distance","set":13,"form":"A"},{"id":1034,"chapter":5,"section":4,"topic":"停止距離","concept":"A-braking","a":true,"q":"路面などの条件が同じなら、速度が2倍になると、制動距離はおおむね4倍になる。","ex":"制動距離はおおむね速度の2乗に比例します。停止距離全体が常に4倍になるという意味ではありません。","fig":"distance","set":13,"form":"A"},{"id":1035,"chapter":5,"section":4,"topic":"徐行","concept":"A-bend","a":false,"q":"道路の曲がり角付近でも、見通しがよければ徐行する必要はない。","ex":"曲がり角付近は徐行する場所です。見通しの良し悪しだけで免除されません。","fig":"slowplaces","set":13,"form":"A"},{"id":1036,"chapter":5,"section":5,"topic":"合図","concept":"A-lane-signal","a":false,"q":"進路変更（車線変更）の合図は、右左折と同じく、進路を変えようとする地点の30m手前に達したときに出すと定められている。","ex":"進路変更の合図は、進路を変えようとする約3秒前です。30m手前に達したときに出すのは右左折・転回の合図です。","fig":"timing","set":13,"form":"A"},{"id":1037,"chapter":5,"section":5,"topic":"合図","concept":"A-hand","a":true,"q":"図の合図は、右折しようとするときにも使える。","ex":"右腕を水平に出す方法は、右折・転回・右への進路変更の合図です。","fig":"handsig","set":13,"visual":"185","form":"A"},{"id":1038,"chapter":5,"section":5,"topic":"進路変更","concept":"A-signal-priority","a":false,"q":"方向指示器を出して十分待てば、後続車に急ブレーキをかけさせる車線変更も認められる。","ex":"合図によって優先権は生じません。後続車に急な回避をさせる進路変更は禁止です。","fig":"lanes","set":13,"form":"A"},{"id":1039,"chapter":5,"section":5,"topic":"警音器","concept":"A-horn","a":true,"q":"衝突を避けるためやむを得ない場合は、警笛鳴らせの標識がなくても警音器を鳴らせる。","ex":"危険回避のためやむを得ない場合は使用できます。単に相手を急がせるためには使えません。","fig":"horn","set":13,"form":"A"},{"id":1040,"chapter":5,"section":6,"topic":"追い越し","concept":"A-priority-pass","a":false,"q":"優先道路を通行中でも、交差点の手前30mは、交差点であることを理由に必ず追い越し禁止になる。","ex":"優先道路を通行している場合は、この場所の規定による追い越し禁止から除かれます。横断歩道等の別の禁止は守ります。","fig":"priority","set":13,"form":"A"},{"id":1041,"chapter":5,"section":6,"topic":"追い越し","concept":"A-tunnel","a":true,"q":"車両通行帯のないトンネルでは、前方が十分に見えていても、自動車を追い越してはいけない。","ex":"通行帯のないトンネルは、自動車・一般原付の追い越し禁止場所です。","fig":"leftpass","set":13,"form":"A"},{"id":1042,"chapter":5,"section":6,"topic":"行き違い","concept":"A-obstacle","a":true,"q":"自分側の工事を避けると対向車の進路に入るので、早めに減速して対向車に道を譲った。","ex":"自分の進路に障害物がある場合は、停止か減速をして対向車に譲ります。","fig":"meeting","set":13,"form":"A"},{"id":1043,"chapter":5,"section":6,"topic":"追い越し","concept":"A-being-passed","a":false,"q":"追い越され始めたが、追い越し先に余裕があるので、自分も速度を上げてよい。","ex":"追い越されている間は、追い越しが終わるまで速度を上げてはいけません。","fig":"passdef","set":13,"form":"A"},{"id":1044,"chapter":5,"section":7,"topic":"交差点","concept":"A-equal-width","a":true,"q":"交通整理も優先道路の指定もなく、同じくらいの幅の交差点では、左方から来る車の進行を妨げない。","ex":"ほかに停止等の規制がないこの条件では、左方から来る車が優先です。","fig":"yield","set":13,"form":"A"},{"id":1045,"chapter":5,"section":7,"topic":"環状交差点","concept":"A-round","a":false,"q":"環状交差点へ入る車は、環状交差点内を走っている車より先に進んでよい。","ex":"進入する車は徐行し、すでに中を走っている車の進行を妨げてはいけません。","fig":"roundabout","set":13,"form":"A"},{"id":1046,"chapter":5,"section":7,"topic":"交差点","concept":"A-rightpath","a":true,"q":"普通自動車で右折するとき、別の通行方法の標示がなければ、交差点の中心のすぐ内側を徐行して通る。","ex":"普通自動車の基本の右折経路です。一方通行でなければ、あらかじめ中央に寄ります。","fig":"turnway","set":13,"form":"A"},{"id":1047,"chapter":5,"section":7,"topic":"交差点","concept":"A-block","a":false,"q":"信号が青なら、交差点の先が詰まって交差点内に止まることが予想されても、進入してよい。","ex":"交差交通を妨げるおそれがあるときは、青でも交差点に入ってはいけません。","fig":"jam2","set":13,"form":"A"},{"id":1048,"chapter":5,"section":9,"topic":"AT車","concept":"A-creep","a":false,"q":"AT車をDに入れて停止中なら、アクセルを踏まない限りブレーキから足を離しても動かない。","ex":"クリープ現象で動くことがあります。停止中はブレーキをしっかり踏みます。","fig":"at-basics","set":13,"form":"A"},{"id":1049,"chapter":5,"section":9,"topic":"運転支援","concept":"A-asv","a":true,"q":"運転支援機能を使っていても、その限界を理解し、自分で前方と周囲を確認し続ける。","ex":"運転支援は、運転者の確認と操作が前提です。自動運行装置と同じものだと考えてはいけません。","fig":"at-basics","set":13,"form":"A"},{"id":1050,"chapter":6,"section":1,"topic":"踏切","concept":"A-rail","a":false,"q":"踏切の警報機が鳴り始めたが、遮断機は上がっているので、すぐに入ればよい。","ex":"警報機が鳴り始めたら進入してはいけません。遮断機が下りるまで待ってよいという意味ではありません。","fig":"railway","set":13,"form":"A"},{"id":1101,"chapter":1,"section":2,"topic":"信号","concept":"B-red-blink","a":true,"q":"赤色の点滅信号でいったん停止し、左右の安全を確かめてから交差点へ進んだ。","ex":"車は赤の点滅で一時停止し、ほかの交通に注意して進みます。","fig":"signals","set":13,"form":"B"},{"id":1102,"chapter":1,"section":2,"topic":"信号","concept":"B-yellow-blink","a":false,"q":"黄の点滅信号には、必ず停止位置で一時停止しなければならないという意味がある。","ex":"黄の点滅自体は一時停止の指示ではなく、他の交通に注意して進めます。別の停止義務があれば従います。","fig":"signals","set":13,"form":"B"},{"id":1103,"chapter":1,"section":2,"topic":"信号","concept":"B-yellow-arrow","a":false,"q":"赤信号と黄色の矢印が同時に表示されたときは、路線バスと路面電車が矢印方向に進める。","ex":"黄色の矢印は路面電車に対する信号です。路線バスは対象ではありません。","fig":"arrowsig","set":13,"form":"B"},{"id":1104,"chapter":1,"section":2,"topic":"信号","concept":"B-turn-red","a":true,"q":"すでに交差点内で右折を始めていた自動車は、信号が赤に変わっても、青で進む車等を妨げずに右折を終えられる。","ex":"すでに右折中なら進めますが、青に従って進む車や路面電車を妨げてはいけません。","fig":"rightturn","set":13,"form":"B"},{"id":1105,"chapter":1,"section":3,"topic":"手信号","concept":"B-horizontal","a":true,"q":"図の手信号を受ける車は、停止位置を越えて進んではならない。","ex":"両腕を水平に上げた警察官の正面へ向かう交通には、赤信号と同じ意味です。","fig":"police","set":13,"visual":"116","form":"B"},{"id":1106,"chapter":1,"section":3,"topic":"手信号","concept":"B-lamp","a":false,"q":"図のように灯火を振っている場合、この車に対する信号は赤である。","ex":"灯火を振っている方向に進む交通は青です。体の正面だけで決めず、灯火の振り方向を見ます。","fig":"police","set":13,"visual":"80","form":"B"},{"id":1107,"chapter":1,"section":2,"topic":"標識","concept":"B-closed","a":true,"q":"図の標識による通行止めは、歩行者にも適用される。","ex":"図は通行止めです。車両だけでなく歩行者も対象です。","fig":"vehicles","set":13,"visual":"50","form":"B"},{"id":1108,"chapter":1,"section":2,"topic":"標識","concept":"B-vehicles","a":true,"q":"図の標識だけでは、歩行者の通行までは禁止されない。","ex":"車両通行止めの対象は車両です。歩行者まで禁止する通行止めとは異なります。","fig":"vehicles","set":13,"visual":"123","form":"B"},{"id":1109,"chapter":1,"section":2,"topic":"補助標識","concept":"B-except","a":true,"q":"図の表示がある場合、自転車はこの標識による車両進入禁止の対象から除かれる。","ex":"自転車は除外されます。「自転車を除く」のような表示は特定小型原付も規制の対象から除きますが、一般原付は除かれません。","fig":"aux-rules","set":13,"visual":"aux-except","form":"B"},{"id":1110,"chapter":1,"section":2,"topic":"標識","concept":"B-warning","a":false,"q":"図の標識は、車両の進入を禁止する規制標識である。","ex":"黄色のひし形は警戒標識です。図は前方の交差点について注意を知らせています。","fig":"signs","set":13,"visual":"27","form":"B"},{"id":1111,"chapter":1,"section":2,"topic":"標識","concept":"B-stopline","a":false,"q":"図の標識を見たら、信号が青で危険がなくても、その標識だけを理由に必ず一時停止する。","ex":"停止線の標識は、停止が必要な場合の位置を示します。単独で一時停止を命じる標識ではありません。","fig":"stopline","set":13,"visual":"76","form":"B"},{"id":1112,"chapter":1,"section":4,"topic":"道路の心得","concept":"B-play","a":false,"q":"交通量の多い道路でも、車が来るたびによければ、道路上でボール遊びをしてよい。","ex":"交通のひんぱんな道路で、交通を妨げる球技などをしてはいけません。","fig":"","set":13,"form":"B"},{"id":1113,"chapter":4,"section":2,"topic":"免許制度","concept":"B-validity","a":true,"q":"交付から6か月を経過して有効期間が切れた仮免許では、指導者が同乗しても路上練習できない。","ex":"仮免許の有効期間は6か月です。指導者の同乗だけでは期限切れを補えません。","fig":"karimen","set":13,"form":"B"},{"id":1114,"chapter":4,"section":2,"topic":"免許制度","concept":"B-at-only","a":false,"q":"AT限定免許でも、運転操作を知っていればMT車を一人で運転できる。","ex":"運転技術があるかどうかとは別に、免許に付されたAT限定の条件を守る必要があります。","fig":"licenses","set":13,"form":"B"},{"id":1115,"chapter":4,"section":2,"topic":"車種","concept":"B-moped","a":true,"q":"125cc以下で最高出力4.0kW以下に制御された新基準原付も、一般原付として扱われる。","ex":"2025年4月からの区分です。通常の125cc二輪車がすべて対象になったわけではありません。","fig":"licenses","set":13,"form":"B"},{"id":1116,"chapter":4,"section":1,"topic":"運転者の心得","concept":"B-alcohol","a":false,"q":"飲酒運転するおそれがあると知っていても、相手が自分で運転する責任を負うなら車を貸してよい。","ex":"飲酒運転をするおそれのある人への車両提供も禁止です。運転者だけの責任にはできません。","fig":"drink","set":13,"form":"B"},{"id":1117,"chapter":5,"section":1,"topic":"発進","concept":"B-start","a":true,"q":"ミラーと目視で後方を確かめてから発進の合図を出し、周囲をもう一度確かめて動き始めた。","ex":"発進前の安全確認は、合図の前と後に行います。死角も直接確かめます。","fig":"start-check","set":13,"form":"B"},{"id":1118,"chapter":5,"section":1,"topic":"運転者の心得","concept":"B-childseat","a":false,"q":"6歳未満の幼児は、助手席の大人がしっかり抱けばチャイルドシートなしで乗せてよい。","ex":"抱いていることは免除理由になりません。法令の例外を除き、幼児用補助装置を使用させます。","fig":"seatbelt","set":13,"form":"B"},{"id":1119,"chapter":5,"section":1,"topic":"発進","concept":"B-mirror","a":false,"q":"ミラーの調整は走り始めてから行う方が、実際の後方の様子を確認できて安全である。","ex":"座席と運転姿勢を整え、発進する前にミラーを調整します。","fig":"posture","set":13,"form":"B"},{"id":1120,"chapter":5,"section":2,"topic":"通行の基本","concept":"B-oneway","a":true,"q":"一方通行の道路では、ほかに規制がなければ、道路の中央から右側の部分も通行できる。","ex":"一方通行は、道路の右側部分を通行できる場合の一つです。右側を自由に駐停車できるという意味ではありません。","fig":"oneway","set":13,"form":"B"},{"id":1121,"chapter":5,"section":2,"topic":"通行の基本","concept":"B-footway","a":true,"q":"駐車場へ入るため歩道を横切る際、歩行者がいなくても歩道の直前で一時停止した。","ex":"道路外へ出入りするため歩道や路側帯を横切るときは、直前で一時停止し、歩行者を妨げないようにします。","fig":"keepleft","set":13,"form":"B"},{"id":1122,"chapter":5,"section":2,"topic":"通行の基本","concept":"B-two-lanes","a":false,"q":"片側2車線の道路で、左車線が空いていても速く走る車は右車線を走り続けてよい。","ex":"原則として左の通行帯を通り、右側は追い越し等のために空けます。","fig":"lanes","set":13,"form":"B"},{"id":1123,"chapter":5,"section":2,"topic":"緊急自動車","concept":"B-emergency-outside","a":false,"q":"交差点から離れた場所で救急車が近づいたので、道を譲れたかどうかに関係なく、その場で直ちに停止すればよい。","ex":"交差点付近以外では、左に寄るなどして進路を譲ります。妨げになる場所で止まるだけでは適切ではありません。","fig":"emergency","set":13,"form":"B"},{"id":1124,"chapter":5,"section":2,"topic":"通行の基本","concept":"B-busstart","a":true,"q":"停留所のバスが発進の合図をしたが、譲るためには急ブレーキが必要だった。この場合は、発進を妨げてはならない規定の例外に当たる。","ex":"急ブレーキや急ハンドルで避ける必要がある場合は例外です。周囲に注意して安全に対応します。","fig":"bus-depart","set":13,"form":"B"},{"id":1125,"chapter":5,"section":3,"topic":"歩行者保護","concept":"B-schoolbus","a":false,"q":"子どもの乗り降りのため止まっている通学通園バスのそばでは、徐行だけで通れる場合は一切ない。","ex":"徐行して安全を確かめて通ります。危険があれば停止しますが、一律に必ず停止という規定ではありません。","fig":"protect","set":13,"form":"B"},{"id":1126,"chapter":5,"section":3,"topic":"歩行者保護","concept":"B-cane","a":true,"q":"白い杖を使う人が歩いているので、警音器で急がせず、徐行または一時停止して安全に通れるようにした。","ex":"白・黄の杖や盲導犬を利用する人などには、徐行または一時停止による保護が必要です。","fig":"protect","set":13,"form":"B"},{"id":1127,"chapter":5,"section":3,"topic":"歩行者保護","concept":"B-clear-crosswalk","a":false,"q":"横断歩道の前では、横断する人がいないことが明らかでも、必ず一時停止しなければならない。","ex":"横断者がいないことが明らかな場合まで、一律の一時停止義務はありません。他の停止規制や危険には従います。","fig":"pedcross","set":13,"form":"B"},{"id":1128,"chapter":5,"section":3,"topic":"路面電車","concept":"B-tram-island","a":true,"q":"安全地帯のある停留所で、乗客が乗り降りしている路面電車の左側を、安全を確かめながら徐行して通過した。","ex":"安全地帯がある場合は、乗降客がいても徐行して通過できます。人の動きにも十分注意します。","fig":"tram","set":13,"form":"B"},{"id":1129,"chapter":5,"section":3,"topic":"歩行者保護","concept":"B-bike-crossing","a":true,"q":"自転車横断帯を渡ろうとしている自転車に対し、手前で停止して先に渡ってもらった。","ex":"自転車横断帯を横断する自転車を優先し、手前で一時停止します。","fig":"pedcross","set":13,"form":"B"},{"id":1130,"chapter":5,"section":4,"topic":"速度","concept":"B-center-speed","a":false,"q":"中央線のある一般道路でも、最高速度の指定がなければ、普通自動車の最高速度は一律30km/hである。","ex":"中央線のある一般道路は、法定最高速度60km/hの区分です。指定や状況による制限には従います。","fig":"speed-2026","set":13,"form":"B"},{"id":1131,"chapter":5,"section":4,"topic":"速度","concept":"B-moped-speed","a":false,"q":"一般原付で最高速度50km/hの標識がある道路を走る場合は、50km/hまで出してよい。","ex":"一般原付の法定最高速度は30km/hです。50の標識があっても上限は30km/hです。","fig":"speed","set":13,"form":"B"},{"id":1132,"chapter":5,"section":4,"topic":"停止距離","concept":"B-reaction","a":true,"q":"同じ速度でも、疲れて反応が遅れると空走距離が伸びる。","ex":"危険に気付いてから制動が始まるまでに時間がかかるほど、その間に進む距離が長くなります。","fig":"distance","set":13,"form":"B"},{"id":1133,"chapter":5,"section":4,"topic":"徐行","concept":"B-blind-priority","a":false,"q":"優先道路でもなく交通整理もない見通しの悪い交差点では、他車が見えなければ徐行しなくてよい。","ex":"この条件の交差点は徐行場所です。見えないことを安全の証拠にしてはいけません。","fig":"slowplaces","set":13,"form":"B"},{"id":1134,"chapter":5,"section":4,"topic":"徐行","concept":"B-definition","a":true,"q":"徐行する際は、単に決まった時速を守るのではなく、直ちに停止できる速度かどうかで判断する。","ex":"徐行は直ちに停止できる速度です。一律に時速10kmなどとは定義されていません。","fig":"slowplaces","set":13,"form":"B"},{"id":1135,"chapter":5,"section":5,"topic":"合図","concept":"B-turn-timing","a":true,"q":"左折する地点の30m手前で合図を始め、左折し終わるまで続けた。","ex":"右左折・転回は30m手前から合図し、行為が終わるまで続けます。","fig":"timing","set":13,"form":"B"},{"id":1136,"chapter":5,"section":5,"topic":"合図","concept":"B-stop-timing","a":false,"q":"減速や停止の合図も、必ずその3秒前から出し始める。","ex":"徐行・停止の合図は、その行為をしようとするときです。進路変更の約3秒前と区別します。","fig":"timing2","set":13,"form":"B"},{"id":1137,"chapter":5,"section":5,"topic":"合図","concept":"B-hand-left","a":false,"q":"図のように右腕のひじを上へ曲げる方法は、右への進路変更を伝える合図である。","ex":"右腕のひじを垂直に上へ曲げる方法は、左折・左への進路変更を表します。","fig":"handsig","set":13,"visual":"184","form":"B"},{"id":1138,"chapter":5,"section":5,"topic":"進路変更","concept":"B-yellow-line","a":false,"q":"黄色の実線で区切られた車線を越えて進路変更するときは、3秒前に合図すれば禁止が解除される。","ex":"合図をしても進路変更禁止は解除されません。車線境界の黄色の線を越えて変更してはいけません。","fig":"lanes","set":13,"form":"B"},{"id":1139,"chapter":5,"section":6,"topic":"追い越し","concept":"B-left-pass","a":true,"q":"右折のため中央へ寄っている前車を追い越すときは、安全を確認してその左側を通る。","ex":"この場合は左側から追い越します。右側から回り込まないようにします。","fig":"leftpass","set":13,"form":"B"},{"id":1140,"chapter":5,"section":6,"topic":"追い越し","concept":"B-crosswalk-pass","a":false,"q":"横断歩道の20m手前では、進路を変えなければ、前を走る自動車の横を通ってその前へ出てもよい。","ex":"横断歩道と手前30m以内では、追い越しに加え、前車の側方を通って前に出る追い抜きも禁止です。","fig":"pass","set":13,"form":"B"},{"id":1141,"chapter":5,"section":6,"topic":"追い越し","concept":"B-tunnel-lanes","a":true,"q":"車両通行帯のあるトンネルは、トンネルであることだけを理由とした追い越し禁止の対象から外れる。","ex":"ただし、追い越し禁止の標識、進路変更禁止や安全確認など、ほかの条件を守る必要があります。","fig":"leftpass","set":13,"form":"B"},{"id":1142,"chapter":5,"section":6,"topic":"行き違い","concept":"B-obstacle","a":false,"q":"自分の車線に止まっている車を避けるときは、先に対向車線へ出てしまえば、対向車に道を譲らせてよい。","ex":"障害物がある側が停止か減速をして、対向車に道を譲ります。先に出て強引に進むのは適切ではありません。","fig":"meeting","set":13,"form":"B"},{"id":1143,"chapter":5,"section":7,"topic":"交差点","concept":"B-wide-road","a":true,"q":"交通整理のない交差点で交差する道路が明らかに広いため、徐行して、その道路の車を先に通した。","ex":"交差する道路が優先道路か明らかに広い場合は、徐行してその道路の車の進行を妨げないようにします。","fig":"yield","set":13,"form":"B"},{"id":1144,"chapter":5,"section":7,"topic":"交差点","concept":"B-opposing","a":false,"q":"右折車は、対向する左折車より先に交差点へ入っていれば、必ず先に曲がれる。","ex":"右折するときは対向する直進車・左折車の進行を妨げてはいけません。進入順だけで優先は決まりません。","fig":"rightturn","set":13,"form":"B"},{"id":1145,"chapter":5,"section":7,"topic":"環状交差点","concept":"B-round-exit","a":true,"q":"環状交差点で、出る予定の出口の一つ手前の出口を通過したので、左の合図を出し始めた。","ex":"通常は出る地点の直前の出口を通過したときから、出終わるまで左の合図を続けます。","fig":"roundabout","set":13,"form":"B"},{"id":1146,"chapter":5,"section":7,"topic":"交差点","concept":"B-left-wrap","a":true,"q":"左折前に左後方を確認し、二輪車を巻き込まないよう、あらかじめできるだけ左端へ寄った。","ex":"左折では左後方の安全確認をし、あらかじめ左端へ寄り、交差点の側端に沿って徐行します。","fig":"turnway","set":13,"form":"B"},{"id":1147,"chapter":5,"section":9,"topic":"AT車","concept":"B-select","a":true,"q":"AT車を後退させるため、ブレーキを踏んだままRに入れ、表示と後方の安全を確認してから動かした。","ex":"シフトを操作するときはブレーキを踏み、位置を目で確かめます。進行方向の安全確認も必要です。","fig":"at-basics","set":13,"form":"B"},{"id":1148,"chapter":5,"section":9,"topic":"AT車","concept":"B-p-moving","a":false,"q":"AT車で坂を下っているとき、速度を落とす目的でPへ切り替えてよい。","ex":"Pは停止後に使います。減速は適切なブレーキ操作や低いギアによるエンジンブレーキで行います。","fig":"at-basics","set":13,"form":"B"},{"id":1149,"chapter":5,"section":9,"topic":"AT車","concept":"B-high-idle","a":true,"q":"エンジン始動直後のAT車は急に動き出すことがあるため、シフト操作時にブレーキを特にしっかり踏んだ。","ex":"回転数が高いときは動き出す力が大きくなることがあります。確実にブレーキを踏みます。","fig":"at-basics","set":13,"form":"B"},{"id":1150,"chapter":6,"section":2,"topic":"坂道・カーブ","concept":"B-refuge","a":false,"q":"上り坂を走る自分のすぐ近くに待避所があるが、上り優先なので、下りの車だけに後退させるのが正しい。","ex":"近くに待避所がある場合は、上り・下りにかかわらず、そこへ入って相手に道を譲ります。","fig":"meeting","set":13,"form":"B"},{"id":1201,"chapter":1,"section":2,"topic":"信号","concept":"C-yellow-blink","a":true,"q":"黄の点滅信号の交差点に近づいたので、他の交通に注意し、必要に応じて速度を落として進んだ。","ex":"黄の点滅は他の交通に注意して進める信号です。危険がある場合の減速や停止は当然必要です。","fig":"signals","set":13,"form":"C"},{"id":1202,"chapter":1,"section":2,"topic":"信号","concept":"C-ped-blink","a":false,"q":"歩行者用の青信号が点滅し始めても、歩行者は車が来ていなければ新たに横断を始めてよい。","ex":"青の点滅では新たな横断を始めてはいけません。横断中なら速やかに渡り終えるか、引き返します。","fig":"pedsig","set":13,"form":"C"},{"id":1203,"chapter":1,"section":2,"topic":"信号","concept":"C-red","a":true,"q":"赤信号で停止線がある場合は、その線の直前で止まり、線を越えて交差点側へ進まない。","ex":"停止位置は停止線の直前です。信号の指示に従って止まります。","fig":"signals","set":13,"form":"C"},{"id":1204,"chapter":1,"section":3,"topic":"手信号","concept":"C-lamp-up","a":true,"q":"灯火が頭上へ上げられる直前の振り方向から進む図の車には、黄信号と同じ意味になる。","ex":"灯火を上げた場合、直前に振っていた方向の交通は黄です。それと交差する交通は赤になります。","fig":"police","set":13,"visual":"189","form":"C"},{"id":1205,"chapter":1,"section":3,"topic":"手信号","concept":"C-front","a":false,"q":"図の車は警察官の腕が横向きなので、青信号と同じと考えてそのまま進める。","ex":"腕の向きだけでなく、自分の進む方向との関係を見ます。正面へ向かう図の車に対しては赤です。","fig":"police","set":13,"visual":"79","form":"C"},{"id":1206,"chapter":1,"section":2,"topic":"信号","concept":"C-left-arrow","a":true,"q":"赤信号と左向きの青矢印が同時に出ているとき、一般原付も左折できる。","ex":"左向きの青矢印では一般原付も進めます。二段階右折の一般原付が右向きの青矢印で直接右折できないこととは別です。","fig":"arrowsig","set":13,"form":"C"},{"id":1207,"chapter":1,"section":2,"topic":"標識","concept":"C-parking-sign","a":true,"q":"図の標識の名称は「駐車禁止」である。","ex":"斜線が1本の図は駐車禁止です。斜線が交差する駐停車禁止との違いを確認します。","fig":"slash","set":13,"visual":"26","form":"C"},{"id":1208,"chapter":1,"section":2,"topic":"標識","concept":"C-stop-slow","a":false,"q":"図の左右の標識は、どちらも一時停止を指示している。","ex":"左は一時停止、右は徐行です。形だけで判断せず、文字と配色も確かめます。","fig":"signs","set":13,"visual":"14","form":"C"},{"id":1209,"chapter":1,"section":2,"topic":"補助標識","concept":"C-time","a":true,"q":"図の標識が示す時間の規制は、午後7時には適用される。","ex":"午後7時は19時なので、8時から20時までの範囲に入ります。","fig":"aux-rules","set":13,"visual":"aux-time","form":"C"},{"id":1210,"chapter":1,"section":2,"topic":"標識","concept":"C-entry-direction","a":false,"q":"図の標識は、どちらの方向からであっても車両がその道路を通行できないことを表す。","ex":"車両進入禁止は、標識がある側からの進入を禁止します。反対側の規制までこの標識だけで決めることはできません。","fig":"noentry","set":13,"visual":"13","form":"C"},{"id":1211,"chapter":1,"section":2,"topic":"標識","concept":"C-uturn","a":false,"q":"図の標識によって禁止されるのは、右折することである。","ex":"図は転回禁止で、Uターンを禁止します。右折禁止を示す標識ではありません。","fig":"slash","set":13,"visual":"73","form":"C"},{"id":1212,"chapter":1,"section":4,"topic":"道路の心得","concept":"C-road-object","a":true,"q":"道路上に交通の妨げとなる物を放置しないようにする。","ex":"交通の妨げとなる物を、みだりに道路に置いてはいけません。車や歩行者の危険につながります。","fig":"","set":13,"form":"C"},{"id":1213,"chapter":4,"section":1,"topic":"運転者の心得","concept":"C-drunk-request","a":false,"q":"飲酒した運転者に自宅へ送ってほしいと頼んでも、自分が運転しなければ問題はない。","ex":"飲酒運転だと知りながら送るよう要求・依頼して同乗することも禁止されています。","fig":"drink","set":13,"form":"C"},{"id":1214,"chapter":4,"section":2,"topic":"免許制度","concept":"C-supervisor","a":true,"q":"仮免許で練習する際、現在免許停止中の人は、過去に長年運転していても指導者にできない。","ex":"免許停止中の人は指導できません。経歴だけでなく、現在その車を運転できる資格も確認します。","fig":"karimen","set":13,"form":"C"},{"id":1215,"chapter":4,"section":1,"topic":"免許制度","concept":"C-glasses","a":true,"q":"免許に「眼鏡等」の条件が付いている場合は、運転前にその条件を満たしていることを確かめる。","ex":"短距離や慣れた道でも、免許に付された条件を守って運転します。","fig":"licenses","set":13,"form":"C"},{"id":1216,"chapter":4,"section":2,"topic":"車種","concept":"C-moped-limit","a":false,"q":"新基準原付として認められた125cc以下の車両は、一般原付の30km/h制限を受けなくなる。","ex":"新基準原付にも一般原付の交通ルールが適用されます。法定最高速度30km/h、二段階右折などの規則も変わりません。","fig":"licenses","set":13,"form":"C"},{"id":1217,"chapter":5,"section":1,"topic":"運転者の心得","concept":"C-passengerbelt","a":false,"q":"運転者が座席ベルトを締めていれば、助手席の同乗者が締めているか確かめる必要はない。","ex":"法令の例外を除き、運転者は同乗者にベルトを着用させる義務があります。","fig":"seatbelt","set":13,"form":"C"},{"id":1218,"chapter":5,"section":1,"topic":"発進","concept":"C-leftdoor","a":true,"q":"交通量の多い場所で乗り降りするときは、安全を確かめ、できるだけ左側のドアを使う。","ex":"車道側のドアを開けると後続車などと接触する危険があります。左側でも周囲の確認は必要です。","fig":"door","set":13,"form":"C"},{"id":1219,"chapter":5,"section":1,"topic":"発進","concept":"C-around-child","a":false,"q":"車が止まっていた時間が短ければ、車の下や前後を確認せずに乗り込んでよい。","ex":"短い時間でも子どもなどが近づくことがあります。乗る前に周囲を確認します。","fig":"start-check","set":13,"form":"C"},{"id":1220,"chapter":5,"section":2,"topic":"通行の基本","concept":"C-designated-lane","a":false,"q":"左折専用と指定された通行帯に入ったが、直進の信号が青なので、そのまま直進してよい。","ex":"進行方向別通行区分が指定されている場合は、その指定にも従います。青信号だけで直進できるわけではありません。","fig":"lanes","set":13,"form":"C"},{"id":1221,"chapter":5,"section":2,"topic":"通行の基本","concept":"C-three-lanes","a":true,"q":"同じ方向へ3本の通行帯がある道路では、原則として最も右の通行帯を追い越し等のために空ける。","ex":"最も右側以外の通行帯を速度に応じて利用し、右側を走り続けないようにします。","fig":"lanes","set":13,"form":"C"},{"id":1222,"chapter":5,"section":2,"topic":"緊急自動車","concept":"C-junction-emergency","a":true,"q":"一方通行ではない交差点付近で緊急自動車が近づいたので、交差点を避けて左に寄り、一時停止した。","ex":"交差点やその付近では、交差点を避けて左側に寄り停止し、進路を譲ります。","fig":"emergency","set":13,"form":"C"},{"id":1223,"chapter":5,"section":2,"topic":"路面電車","concept":"C-tracks","a":false,"q":"路面電車が見えず、自分の通行を認める標識等もないので、渋滞回避のため軌道敷内を走り続けてよい。","ex":"軌道敷内は原則通行禁止です。電車が見えないことや渋滞は、走行し続ける理由になりません。","fig":"tracks","set":13,"form":"C"},{"id":1224,"chapter":5,"section":2,"topic":"通行の基本","concept":"C-footpath","a":true,"q":"店舗へ入るため歩道を横切る際は、直前で一時停止して、歩行者の通行を妨げないことを確認する。","ex":"歩道を横切るときは、歩行者の有無にかかわらず、直前の停止と安全確認が必要です。","fig":"keepleft","set":13,"form":"C"},{"id":1225,"chapter":5,"section":3,"topic":"歩行者保護","concept":"C-pushing-cycle","a":true,"q":"自転車を押して歩いている人が横断歩道を渡ろうとしているので、手前で止まって道を譲った。","ex":"自転車を押して歩いている人は歩行者として扱われます。横断歩道の歩行者保護を行います。","fig":"pedcross","set":13,"form":"C"},{"id":1226,"chapter":5,"section":3,"topic":"歩行者保護","concept":"C-safety-island","a":false,"q":"歩行者がいない安全地帯のそばでも、安全地帯があることだけを理由に必ず徐行しなければならない。","ex":"安全地帯のそばでこの徐行義務が生じるのは、そこに歩行者がいるときです。他の徐行理由は別に判断します。","fig":"safety","set":13,"form":"C"},{"id":1227,"chapter":5,"section":3,"topic":"歩行者保護","concept":"C-gap","a":true,"q":"横断歩道や一人歩きの子どもなどの特別な保護の場面でなければ、歩行者のそばでは安全な間隔を空けるか徐行する。","ex":"一般原則は安全な間隔または徐行です。特別の停止・徐行義務がある場面には、その規定が優先します。","fig":"protect","set":13,"form":"C"},{"id":1228,"chapter":5,"section":3,"topic":"歩行者保護","concept":"C-splash","a":true,"q":"水たまりの横に歩行者がいるので、水をはねないように速度を落とした。","ex":"ぬかるみや水たまりでは、徐行などにより泥や水をはねないようにします。","fig":"protect","set":13,"form":"C"},{"id":1229,"chapter":5,"section":4,"topic":"速度","concept":"C-divider","a":false,"q":"中央分離帯で往復方向が分かれた一般道路は、速度指定がない場合でも普通自動車は必ず30km/h以下で走らなければならない。","ex":"構造的に往復方向が分離された一般道路は、法定最高速度60km/hの区分です。","fig":"speed-2026","set":13,"form":"C"},{"id":1230,"chapter":5,"section":4,"topic":"速度","concept":"C-edge","a":false,"q":"道路の端に白い線があるだけで、普通自動車の法定最高速度は必ず60km/hになる。","ex":"車道外側線と中央線は違います。中央線・通行帯・上下線の構造的分離の有無や指定速度等を確認します。","fig":"speed-2026","set":13,"form":"C"},{"id":1231,"chapter":5,"section":4,"topic":"停止距離","concept":"C-wet","a":false,"q":"走る速度が同じなら、路面が雨でぬれていても、乾いた路面と停止距離は変わらない。","ex":"ぬれた路面では制動距離が伸び、停止距離も長くなります。速度と車間距離を調整します。","fig":"stop60","set":13,"form":"C"},{"id":1232,"chapter":5,"section":4,"topic":"速度","concept":"C-sudden-brake","a":true,"q":"危険を避けるためやむを得ない場合を除き、急ブレーキを避ける。","ex":"不必要な急ブレーキは後続車の追突などにつながります。早めの判断と穏やかな操作を心がけます。","fig":"distance","set":13,"form":"C"},{"id":1233,"chapter":5,"section":4,"topic":"停止距離","concept":"C-speed-reaction","a":true,"q":"反応時間が変わらなければ、40km/hから80km/hへ速度が上がると、空走距離は約2倍になる。","ex":"反応中に進む距離は速度に比例します。これは制動距離の2乗の関係とは別です。","fig":"distance","set":13,"form":"C"},{"id":1234,"chapter":5,"section":5,"topic":"合図","concept":"C-empty-road","a":false,"q":"周囲に他車が見えなければ、右左折時の方向指示器を省いてもよい。","ex":"ほかの交通が見えなくても、右左折に必要な合図は省略できません。","fig":"timing2","set":13,"form":"C"},{"id":1235,"chapter":5,"section":5,"topic":"合図","concept":"C-hand-down","a":true,"q":"図のように右腕を斜め下へ伸ばして静止させる方法は、徐行・停止の合図である。","ex":"腕を車の外に出して斜め下へ伸ばし、静止させるのは徐行・停止の合図です。後退の合図は、斜め下に伸ばした腕を手のひらを後ろへ向けて前後に動かします。","fig":"handsig","set":13,"visual":"186","form":"C"},{"id":1236,"chapter":5,"section":5,"topic":"合図","concept":"C-change","a":true,"q":"右へ車線変更するため、約3秒前に右の合図を出し、安全を確認して変更を終えたところで合図をやめた。","ex":"進路変更は約3秒前から、変更が終わるまで合図します。合図と安全確認は両方必要です。","fig":"timing","set":13,"form":"C"},{"id":1237,"chapter":5,"section":5,"topic":"警音器","concept":"C-horn-zone","a":false,"q":"警笛区間に入ったら、見通しがよい直線部分でも警音器を鳴らし続けなければならない。","ex":"鳴らす場所は、区間内の見通しのきかない交差点・曲がり角・上り坂の頂上です。","fig":"horn","set":13,"form":"C"},{"id":1238,"chapter":5,"section":6,"topic":"追い越し","concept":"C-double-pass","a":true,"q":"前車が別の自動車を追い越そうとしているので、その前車をさらに追い越すことはしない。","ex":"自動車を追い越そうとしている自動車をさらに追い越す二重追い越しは禁止です。","fig":"passdef","set":13,"form":"C"},{"id":1239,"chapter":5,"section":2,"topic":"通行の基本","concept":"C-cycle-gap","a":false,"q":"進路を変えず自転車の右側を通過するときは、間隔が十分でなくても、制限速度内なら速度を落とす必要はない。","ex":"十分な間隔がないときは、その間隔に応じた安全な速度で通過します。制限速度を守るだけでは足りません。2026年4月施行の規定です。","fig":"cycle-gap","set":13,"form":"C"},{"id":1240,"chapter":5,"section":2,"topic":"通行の基本","concept":"C-white-center","a":true,"q":"左側部分が6m未満で白い破線の中央線の道路では、見通し・対向交通・追い越し禁止の有無などの条件を満たせば、右側にはみ出して追い越せる。","ex":"白い破線だけで可否は決まりません。道路幅や安全、ほかの禁止も確認します。","fig":"centerline","set":13,"form":"C"},{"id":1241,"chapter":5,"section":6,"topic":"追い越し","concept":"C-speed-pass","a":false,"q":"最高速度40km/hの区間でも、追い越す間だけ50km/hに上げることは認められる。","ex":"追い越しのためであっても最高速度は超えられません。安全に完了できないときは控えます。","fig":"passdef","set":13,"form":"C"},{"id":1242,"chapter":5,"section":7,"topic":"環状交差点","concept":"C-first-exit","a":true,"q":"環状交差点で最初の出口から出るため、入ったときから左の合図を出した。","ex":"最初の出口から出る場合は、進入したときから合図を始め、出終わるまで続けます。","fig":"roundabout","set":13,"form":"C"},{"id":1243,"chapter":5,"section":7,"topic":"交差点","concept":"C-oneway-right","a":false,"q":"一方通行で右折する際も、必ず道路の中央に寄って右折する。","ex":"一方通行では、あらかじめできるだけ右端へ寄ります。通行方法の標示があるときはそれに従います。","fig":"oneway","set":13,"form":"C"},{"id":1244,"chapter":5,"section":7,"topic":"交差点","concept":"C-inner-wheel","a":true,"q":"自動車が曲がるときは後輪が前輪より内側を通るため、左折時は左後方の巻き込みに注意する。","ex":"前輪と後輪の通る位置の差が内輪差です。特に大型車では大きくなります。","fig":"naurinsa","set":13,"form":"C"},{"id":1245,"chapter":5,"section":7,"topic":"交差点","concept":"C-priority-left","a":false,"q":"交通整理のない交差点で自分が優先道路を走っている場合でも、左側の狭い道路から来る車が常に優先する。","ex":"優先道路の関係を先に確認します。左方優先をすべての交差点に一律に当てはめてはいけません。","fig":"yield","set":13,"form":"C"},{"id":1246,"chapter":5,"section":7,"topic":"交差点","concept":"C-priority-turn","a":true,"q":"優先道路から右折するときも、右折するための徐行と、対向車・歩行者の安全確認は必要である。","ex":"優先道路による例外は、ほかの徐行・歩行者保護の義務までなくすものではありません。","fig":"priority","set":13,"form":"C"},{"id":1247,"chapter":5,"section":9,"topic":"AT車","concept":"C-start-brake","a":true,"q":"AT車の始動前にブレーキとアクセルの位置を確かめ、Pと駐車ブレーキを確認し、ブレーキを踏んで始動した。","ex":"ペダルの踏み間違いと意図しない発進を防ぐため、発進準備を確実に行います。","fig":"at-basics","set":13,"form":"C"},{"id":1248,"chapter":5,"section":9,"topic":"運転支援","concept":"C-asv","a":false,"q":"衝突被害軽減ブレーキが付いていれば、歩行者を必ず検知して停止するので、運転者はブレーキの準備をしなくてよい。","ex":"検知や作動には限界があります。過信せず、運転者が周囲を確認して必要な操作をします。","fig":"at-basics","set":13,"form":"C"},{"id":1249,"chapter":5,"section":9,"topic":"AT車","concept":"C-downhill","a":true,"q":"長い急な下り坂では、Dのままフットブレーキだけに頼らず、適切に低いギアを選んでエンジンブレーキも使う。","ex":"フットブレーキの使い過ぎを避けます。ギアの選び方は車種の操作方法に従います。","fig":"atgear","set":13,"form":"C"},{"id":1250,"chapter":6,"section":2,"topic":"坂道・カーブ","concept":"C-cliff","a":false,"q":"片側が崖で安全にすれ違えない道路では、転落の危険がある崖側の車が動き続け、山側の車だけが停止して譲る。","ex":"この場合は崖側の車があらかじめ停止し、道を譲ります。転落の危険を避けるためです。","fig":"meeting","set":13,"form":"C"}];
const BANK=[...Q,...ASSESSMENT_Q];
const ASSESSMENT_FORMS=Object.fromEntries(["A","B","C"].map(f=>[f,ASSESSMENT_Q.filter(q=>q.form===f)]));
const BLUEPRINT_VERSION=1;
const EXAM_BLUEPRINT=[{"chapter":1,"count":12,"short":"共通の心得"},{"chapter":4,"count":4,"short":"運転前"},{"chapter":5,"count":33,"short":"運転方法"},{"chapter":6,"count":1,"short":"危険な場所等"}];

const bankIds=new Set();for(const q of BANK){if(!Number.isInteger(q.id)||bankIds.has(q.id)||typeof q.q!=='string'||typeof q.a!=='boolean'||typeof q.ex!=='string')throw new Error('問題データの形式を確認してください');bankIds.add(q.id);}
